  `gamme` = '[{"name":"Cosacos","color":"#E0C88A","force":"Mild","story":"Cosaco : 5 3/8 pouces sur cepo 42 (environ 137 mm) selon Wikipédia et un détaillant britannique, qui le dit proche d''un petit corona, en tripa larga et totalmente a mano, de force légère, enveloppé de papier de soie blanc.","vitolas":["Cosaco"],"wrapper":"Cape non précisée"},{"name":"No.1","color":"#D4B44A","force":"Mild","story":"No. 1 : 6 3/8 pouces sur cepo 44 (environ 162 mm), lonsdale, selon Wikipédia ; la maison ne donne aucune cote.","vitolas":["No. 1"],"wrapper":"Cape non précisée"},{"name":"Delicias","color":"#D4B44A","force":"Mild","wrapper":"Cape non précisée","vitolas":[],"story":"Delicia : 4 7/8 pouces sur cepo 40 (environ 124 mm) selon Wikipédia, qui le dit seul format en tripe courte ; un détaillant britannique donne 4 3/4 sur 40."}]',
  `gamme_en` = '[{"name":"Cosacos","color":"#E0C88A","force":"Mild","story":"Cosaco: 5 3/8 inches with a cepo 42 (about 137 mm) according to Wikipedia and a British retailer, who calls it close to a petit corona, in long filler and totalmente a mano, of light strength, wrapped in white tissue paper.","vitolas":["Cosaco"],"wrapper":"Wrapper not specified"},{"name":"No.1","color":"#D4B44A","force":"Mild","story":"No. 1: 6 3/8 inches with a cepo 44 (about 162 mm), lonsdale, according to Wikipedia; the house gives no dimensions.","vitolas":["No. 1"],"wrapper":"Wrapper not specified"},{"name":"Delicias","color":"#D4B44A","force":"Mild","wrapper":"Wrapper not specified","vitolas":[],"story":"Delicia: 4 7/8 inches with a cepo 40 (about 124 mm) according to Wikipedia, which calls it the only short filler format; a British retailer gives 4 3/4 by 40."}]',
  `gamme_es` = '[{"name":"Cosacos","color":"#E0C88A","force":"Mild","story":"Cosaco: 5 3/8 pulgadas con cepo 42 (unos 137 mm) según Wikipedia y un minorista británico, que lo dice cercano a un petit corona, en tripa larga y totalmente a mano, de fuerza ligera, envuelto en papel de seda blanco.","vitolas":["Cosaco"],"wrapper":"Capa no precisada"},{"name":"No.1","color":"#D4B44A","force":"Mild","story":"No. 1: 6 3/8 pulgadas con cepo 44 (unos 162 mm), lonsdale, según Wikipedia; la casa no da ninguna medida.","vitolas":["No. 1"],"wrapper":"Capa no precisada"},{"name":"Delicias","color":"#D4B44A","force":"Mild","wrapper":"Capa no precisada","vitolas":[],"story":"Delicia: 4 7/8 pulgadas con cepo 40 (unos 124 mm) según Wikipedia, que lo dice único formato con tripa corta; un minorista británico da 4 3/4 por 40."}]',
  `gamme_de` = '[{"name":"Cosacos","color":"#E0C88A","force":"Mild","story":"Cosaco: 5 3/8 Zoll bei cepo 42 (etwa 137 mm) laut Wikipedia und einem britischen Einzelhändler, der es einer Petit Corona nahe nennt, als Longfiller und totalmente a mano, von leichter Stärke, in weißes Seidenpapier gewickelt.","vitolas":["Cosaco"],"wrapper":"Deckblatt nicht angegeben"},{"name":"No.1","color":"#D4B44A","force":"Mild","story":"No. 1: 6 3/8 Zoll bei cepo 44 (etwa 162 mm), Lonsdale, laut Wikipedia; das Haus gibt keine Maße an.","vitolas":["No. 1"],"wrapper":"Deckblatt nicht angegeben"},{"name":"Delicias","color":"#D4B44A","force":"Mild","wrapper":"Deckblatt nicht angegeben","vitolas":[],"story":"Delicia: 4 7/8 Zoll bei cepo 40 (etwa 124 mm) laut Wikipedia, die es als einziges Format mit Shortfiller nennt; ein britischer Einzelhändler gibt 4 3/4 mal 40 an."}]',
  `gamme_zh` = '[{"name":"Cosacos","color":"#E0C88A","force":"Mild","story":"Cosaco：5 3/8 英寸，cepo 42（约137毫米），据维基百科和一家英国零售商；后者称其接近 petit corona，长茄芯、全手工卷制，浓度轻，裹以白色棉纸。","vitolas":["Cosaco"],"wrapper":"茄衣未注明"},{"name":"No.1","color":"#D4B44A","force":"Mild","story":"No. 1：6 3/8 英寸，cepo 44（约162毫米），lonsdale，据维基百科；品牌方未给出任何尺寸。","vitolas":["No. 1"],"wrapper":"茄衣未注明"},{"name":"Delicias","color":"#D4B44A","force":"Mild","wrapper":"茄衣未注明","vitolas":[],"story":"Delicia：4 7/8 英寸，cepo 40（约124毫米），据维基百科，它是唯一的短茄芯规格；一家英国零售商给出的是 4 3/4 x 40。"}]',
  `gamme_ar` = '[{"name":"Cosacos","color":"#E0C88A","force":"Mild","story":"Cosaco: 5 3/8 بوصة بـcepo 42 (نحو 137 مم) بحسب ويكيبيديا وتاجر تجزئة بريطاني، يقول إنه قريب من petit corona، بحشوة طويلة ومصنوع كليًّا باليد، خفيف القوة، ملفوف بورق حريري أبيض.","vitolas":["Cosaco"],"wrapper":"الغلاف غير مذكور"},{"name":"No.1","color":"#D4B44A","force":"Mild","story":"No. 1: 6 3/8 بوصة بـcepo 44 (نحو 162 مم)، lonsdale، بحسب ويكيبيديا؛ ولا تعطي الدار أي مقاس.","vitolas":["No. 1"],"wrapper":"الغلاف غير مذكور"},{"name":"Delicias","color":"#D4B44A","force":"Mild","wrapper":"الغلاف غير مذكور","vitolas":[],"story":"Delicia: 4 7/8 بوصة بـcepo 40 (نحو 124 مم) بحسب ويكيبيديا، التي تقول إنه القياس الوحيد بحشوة قصيرة؛ ويعطي تاجر تجزئة بريطاني 4 3/4 في 40."}]',
  `celebrities` = '[{"name":"Francisco E. Fonseca","anecdote":"Habanos le nomme Don Francisco Fonseca, fondateur de la marque dans la dernière décennie du XIXe siècle, élégant et soucieux de l''apparence, ce qu''il aurait transmis à la présentation de ses Habanos. Wikipédia, qui cite le New York Times du 26 octobre 1929, le dit né à Manzanillo et mort à La Havane en 1929."}]',
  `celebrities_en` = '[{"name":"Francisco E. Fonseca","anecdote":"Habanos names him Don Francisco Fonseca, founder of the brand in the last decade of the nineteenth century, elegant and careful of appearance, which he is said to have passed on to the presentation of his Habanos. Wikipedia, which cites the New York Times of 26 October 1929, says he was born in Manzanillo and died in Havana in 1929."}]',
  `celebrities_es` = '[{"name":"Francisco E. Fonseca","anecdote":"Habanos lo nombra Don Francisco Fonseca, fundador de la marca en la última década del siglo XIX, elegante y atento a la apariencia, lo que habría transmitido a la presentación de sus Habanos. Wikipedia, que cita el New York Times del 26 de octubre de 1929, lo dice nacido en Manzanillo y muerto en La Habana en 1929."}]',
  `celebrities_de` = '[{"name":"Francisco E. Fonseca","anecdote":"Habanos nennt ihn Don Francisco Fonseca, Gründer der Marke im letzten Jahrzehnt des 19. Jahrhunderts, elegant und auf sein Äußeres bedacht, was er auf die Aufmachung seiner Habanos übertragen haben soll. Wikipedia, die die New York Times vom 26. Oktober 1929 zitiert, sagt, er sei in Manzanillo geboren und 1929 in Havanna gestorben."}]',
  `celebrities_zh` = '[{"name":"Francisco E. Fonseca","anecdote":"Habanos 称他为 Don Francisco Fonseca，是该品牌在十九世纪末十年间的创始人，优雅而注重仪表，据说他把这一点传给了自己 Habanos 的呈现方式。维基百科引用1929年10月26日的 New York Times，称他生于 Manzanillo，1929年在哈瓦那去世。"}]',
  `celebrities_ar` = '[{"name":"Francisco E. Fonseca","anecdote":"تسمّيه Habanos Don Francisco Fonseca، مؤسِّس العلامة في العقد الأخير من القرن التاسع عشر، أنيقًا يعنى بمظهره، وهو ما يُقال إنه نقله إلى تقديم Habanos التي يصنعها. وتقول ويكيبيديا، التي تستشهد بجريدة New York Times في 26 أكتوبر 1929، إنه وُلد في Manzanillo وتوفي في هافانا عام 1929."}]',
  `pairings` = '[{"type":"Café","name":"Café filtre léger","notes":"Suggestion pour une marque que Habanos dit de force légère."},{"type":"Vin","name":"Champagne blanc de blancs","notes":"Suggestion ; Habanos dit la marque idéale pour accompagner des repas légers."}]',
  `pairings_en` = '[{"type":"Coffee","name":"Light filter coffee","notes":"A suggestion for a brand that Habanos says is light in strength."},{"type":"Wine","name":"Blanc de blancs champagne","notes":"A suggestion; Habanos says the brand is ideal to accompany light meals."}]',
  `pairings_es` = '[{"type":"Café","name":"Café de filtro ligero","notes":"Sugerencia para una marca que Habanos dice de fuerza ligera."},{"type":"Vino","name":"Champán blanc de blancs","notes":"Sugerencia; Habanos dice la marca ideal para acompañar comidas ligeras."}]',
  `pairings_de` = '[{"type":"Kaffee","name":"Leichter Filterkaffee","notes":"Vorschlag für eine Marke, die Habanos als leicht in der Stärke bezeichnet."},{"type":"Wein","name":"Blanc de Blancs Champagner","notes":"Vorschlag; Habanos nennt die Marke ideal zur Begleitung leichter Mahlzeiten."}]',
  `pairings_zh` = '[{"type":"咖啡","name":"清淡滤泡咖啡","notes":"为 Habanos 称浓度轻的品牌提供的建议。"},{"type":"葡萄酒","name":"白中白香槟","notes":"建议；Habanos 称该品牌宜搭配清淡的餐食。"}]',
  `pairings_ar` = '[{"type":"قهوة","name":"قهوة مرشَّحة خفيفة","notes":"اقتراح لعلامة تقول Habanos إنها خفيفة القوة."},{"type":"نبيذ","name":"شمبانيا بلان دو بلان","notes":"اقتراح؛ وتقول Habanos إنّ العلامة ملائمة لمرافقة وجبات خفيفة."}]',
  `source` = IF(LOCATE(CAST('d''autres sources 1891 — l''atlas retient 1892 et écrit la variance ; cubancigarwebsite.com et cigaraficionado.com (2011, 2016) ne nomment pas sa fabrique mère ;' AS BINARY), CAST(`source` AS BINARY)) > 0, REPLACE(`source`, 'd''autres sources 1891 — l''atlas retient 1892 et écrit la variance ; cubancigarwebsite.com et cigaraficionado.com (2011, 2016) ne nomment pas sa fabrique mère ;', 'marque enregistrée en 1907 selon la même page ; cigarsunlimited.co.uk : années 1890, développée en 1906 ; la presse du métier (2011) ne cite pas Fonseca parmi les marques des fabriques ;'), `source`),
  `source` = IF(LOCATE(CAST('en.wikipedia.org « Fonseca (cigar brand) » (sans date : 1892' AS BINARY), CAST(`source` AS BINARY)) > 0, `source`, CONCAT(`source`, ' ; ', 'en.wikipedia.org « Fonseca (cigar brand) » (sans date : 1892, enregistrée 1907 ; Cosaco 5 3/8 x 42, Delicia, No. 1, KDT Cadete ; fabrique Lázaro Peña) ; cigarsunlimited.co.uk « Fonseca Cosacos » (sans date : 5 3/8 x 42, tripa larga, Vuelta Abajo) ; cigaraficionado.com « Bolder Fonseca from MATASA » (18 février 2013 : homonyme non cubain, MATASA, République dominicaine) ; habanos.com « The Habanos Brands Academia » (octobre 2026 : Rest of brands)')),
  `updated_at` = NOW()
 WHERE `name` = 'Fonseca';

-- ── H. Upmann ──
UPDATE `brands` SET
  `gamme` = '[{"name":"Sir Winston","color":"#8B6914","force":"Mild-Medium","story":"Vitola de galera Julieta No 2, cepo 47 x 178 mm, dit habanos.com. C''est dans ce format que la marque a sorti sa première Gran Reserva, Cosecha 2011 : 5 000 coffrets laqués numérotés de 15, feuilles de la Vuelta Abajo récoltées en 2011 et vieillies cinq ans. Habanos décrit la marque comme de force légère à moyenne.","vitolas":["Sir Winston"],"wrapper":"Vuelta Abajo"},{"name":"Magnum","color":"#A0522D","force":"Mild-Medium","story":"Habanos écrit que le Magnum 46 et le Magnum 50, présenté en 2008, forment une ligne à part, à la présentation distincte ; le Magnum 54 entre dans la gamme régulière en 2016. Le Magnum 46 mesure 5 5/8 pouces (143 mm) pour un cepo 46 ; le Magnum 50, 160 mm pour un cepo 50 ; le Magnum 54, 4 3/4 pouces (120 mm) pour un cepo 54, selon un détaillant et une revue de 2017 (la page de la maison ne donne pas ses cotes). La maison range la ligne Magnum parmi ses Habanos de force douce à moyenne.","vitolas":["Magnum 46","Magnum 50","Magnum 54"],"wrapper":"Vuelta Abajo"},{"name":"Connoisseur","color":"#722F37","force":"Mild-Medium","story":"Habanos parle d''une « historic Connossieur Linea » (orthographe de ses communiqués). Le No. 1 mesure 5 pouces (127 mm) pour un cepo 48 et restait en pleine production en octobre 2013, a confirmé la maison. Le Connossieur A (Genios, cepo 52 x 140 mm, 9 octobre 2013) est destiné aux seuls Habanos Specialists et Casas del Habano ; le B (5 7/8 pouces, cepo 54), exclusif aux Casas del Habano et aux Habanos Specialists, est lancé au XIXe Festival del Habano selon Cigar Coop (16 mars 2017), alors que la presse du métier le date de 2018 ; le No. 2 (cepo 51 x 134 mm, de fortaleza suave selon Habanos), présenté à Berlin le 24 novembre 2020, porte la ligne à quatre formats.","vitolas":["Connoisseur No.1","Connossieur A","Connossieur B","Connossieur No.2"],"wrapper":"Vuelta Abajo"},{"name":"Half Corona","color":"#8B4513","force":"Mild-Medium","story":"Vitola de 44 x 90 mm présentée au XIIIe Festival del Habano, en février 2011. Habanos la dit de force douce à moyenne, très aromatique et de goût équilibré, et y voit une invitation à une fumée courte.","vitolas":["Half Corona"],"wrapper":"Vuelta Abajo"}]',
  `gamme_en` = '[{"name":"Sir Winston","color":"#8B6914","force":"Mild-Medium","story":"Vitola de galera Julieta No 2, cepo 47 x 178 mm, says habanos.com. The brand released its first Gran Reserva, Cosecha 2011, in this format: 5 000 numbered lacquered boxes of 15, with Vuelta Abajo leaves harvested in 2011 and aged for five years. Habanos describes the brand as light to medium in strength.","vitolas":["Sir Winston"],"wrapper":"Vuelta Abajo"},{"name":"Magnum","color":"#A0522D","force":"Mild-Medium","story":"Habanos writes that the Magnum 46 and the Magnum 50, presented in 2008, form a separate line with a distinct presentation; the Magnum 54 joins the regular range in 2016. The Magnum 46 measures 5 5/8 inches (143 mm) with a cepo 46; the Magnum 50, 160 mm with a cepo 50; the Magnum 54, 4 3/4 inches (120 mm) with a cepo 54, according to a retailer and a 2017 magazine (the house''s page does not give its dimensions). The house ranks the Magnum line among its Habanos of mild to medium strength.","vitolas":["Magnum 46","Magnum 50","Magnum 54"],"wrapper":"Vuelta Abajo"},{"name":"Connoisseur","color":"#722F37","force":"Mild-Medium","story":"Habanos speaks of a “historic Connossieur Linea” (the spelling of its press releases). The No. 1 measures 5 inches (127 mm) with a cepo 48 and was still in full production in October 2013, the house confirmed. The Connossieur A (Genios, cepo 52 x 140 mm, 9 October 2013) is intended only for Habanos Specialists and Casas del Habano; the B (5 7/8 inches, cepo 54), exclusive to the Casas del Habano and the Habanos Specialists, is launched at the XIX Festival del Habano according to Cigar Coop (16 March 2017), whereas the trade press dates it to 2018; the No. 2 (cepo 51 x 134 mm, mild in strength according to Habanos), presented in Berlin on 24 November 2020, brings the line to four formats.","vitolas":["Connoisseur No.1","Connossieur A","Connossieur B","Connossieur No.2"],"wrapper":"Vuelta Abajo"},{"name":"Half Corona","color":"#8B4513","force":"Mild-Medium","story":"A 44 x 90 mm vitola presented at the thirteenth Festival del Habano, in February 2011. Habanos calls it mild to medium in strength, very aromatic and balanced in taste, and sees in it an invitation to a short smoke.","vitolas":["Half Corona"],"wrapper":"Vuelta Abajo"}]',
  `gamme_es` = '[{"name":"Sir Winston","color":"#8B6914","force":"Mild-Medium","story":"Vitola de galera Julieta No 2, cepo 47 x 178 mm, dice habanos.com. En este formato la marca sacó su primera Gran Reserva, Cosecha 2011: 5 000 cofres lacados numerados de 15, hojas de la Vuelta Abajo cosechadas en 2011 y envejecidas cinco años. Habanos describe la marca como de fuerza ligera a media.","vitolas":["Sir Winston"],"wrapper":"Vuelta Abajo"},{"name":"Magnum","color":"#A0522D","force":"Mild-Medium","story":"Habanos escribe que el Magnum 46 y el Magnum 50, presentado en 2008, forman una línea aparte, de presentación distinta; el Magnum 54 entra en la gama regular en 2016. El Magnum 46 mide 5 5/8 pulgadas (143 mm) para un cepo 46; el Magnum 50, 160 mm para un cepo 50; el Magnum 54, 4 3/4 pulgadas (120 mm) para un cepo 54, según un minorista y una revista de 2017 (la página de la casa no da sus medidas). La casa clasifica la línea Magnum entre sus Habanos de fuerza suave a media.","vitolas":["Magnum 46","Magnum 50","Magnum 54"],"wrapper":"Vuelta Abajo"},{"name":"Connoisseur","color":"#722F37","force":"Mild-Medium","story":"Habanos habla de una «historic Connossieur Linea» (ortografía de sus comunicados). El No. 1 mide 5 pulgadas (127 mm) para un cepo 48 y seguía en plena producción en octubre de 2013, confirmó la casa. El Connossieur A (Genios, cepo 52 x 140 mm, 9 de octubre de 2013) está destinado únicamente a los Habanos Specialists y a las Casas del Habano; el B (5 7/8 pulgadas, cepo 54), exclusivo de las Casas del Habano y de los Habanos Specialists, se lanza en el XIX Festival del Habano según Cigar Coop (16 de marzo de 2017), mientras que la prensa del oficio lo fecha en 2018; el No. 2 (cepo 51 x 134 mm, de fortaleza suave según Habanos), presentado en Berlín el 24 de noviembre de 2020, lleva la línea a cuatro formatos.","vitolas":["Connoisseur No.1","Connossieur A","Connossieur B","Connossieur No.2"],"wrapper":"Vuelta Abajo"},{"name":"Half Corona","color":"#8B4513","force":"Mild-Medium","story":"Vitola de 44 x 90 mm presentada en el XIII Festival del Habano, en febrero de 2011. Habanos la dice de fuerza suave a media, muy aromática y de gusto equilibrado, y ve en ella una invitación a una fumada corta.","vitolas":["Half Corona"],"wrapper":"Vuelta Abajo"}]',
  `gamme_de` = '[{"name":"Sir Winston","color":"#8B6914","force":"Mild-Medium","story":"Vitola de galera Julieta No 2, cepo 47 x 178 mm, sagt habanos.com. In diesem Format brachte die Marke ihre erste Gran Reserva heraus, Cosecha 2011: 5 000 nummerierte Lackkassetten zu je 15, Blätter aus der Vuelta Abajo, 2011 geerntet und fünf Jahre lang gereift. Habanos beschreibt die Marke als von leichter bis mittlerer Stärke.","vitolas":["Sir Winston"],"wrapper":"Vuelta Abajo"},{"name":"Magnum","color":"#A0522D","force":"Mild-Medium","story":"Habanos schreibt, dass die Magnum 46 und die Magnum 50, 2008 vorgestellt, eine eigene Linie mit eigener Aufmachung bilden; die Magnum 54 kommt 2016 in das reguläre Sortiment. Die Magnum 46 misst 5 5/8 Zoll (143 mm) bei einem cepo 46; die Magnum 50 160 mm bei einem cepo 50; die Magnum 54 4 3/4 Zoll (120 mm) bei einem cepo 54, laut einem Einzelhändler und einer Zeitschrift von 2017 (die Seite des Hauses gibt ihre Maße nicht an). Das Haus zählt die Linie Magnum zu seinen Habanos von milder bis mittlerer Stärke.","vitolas":["Magnum 46","Magnum 50","Magnum 54"],"wrapper":"Vuelta Abajo"},{"name":"Connoisseur","color":"#722F37","force":"Mild-Medium","story":"Habanos spricht von einer „historic Connossieur Linea“ (Schreibweise seiner Pressemitteilungen). Die No. 1 misst 5 Zoll (127 mm) bei einem cepo 48 und befand sich im Oktober 2013 in voller Produktion, bestätigte das Haus. Die Connossieur A (Genios, cepo 52 x 140 mm, 9. Oktober 2013) ist allein für Habanos Specialists und Casas del Habano bestimmt; die B (5 7/8 Zoll, cepo 54), exklusiv für die Casas del Habano und die Habanos Specialists, wird laut Cigar Coop (16. März 2017) auf dem XIX Festival del Habano vorgestellt, während die Fachpresse sie auf 2018 datiert; die No. 2 (cepo 51 x 134 mm, von milder Stärke laut Habanos), am 24. November 2020 in Berlin vorgestellt, bringt die Linie auf vier Formate.","vitolas":["Connoisseur No.1","Connossieur A","Connossieur B","Connossieur No.2"],"wrapper":"Vuelta Abajo"},{"name":"Half Corona","color":"#8B4513","force":"Mild-Medium","story":"Vitola von 44 x 90 mm, beim dreizehnten Festival del Habano im Februar 2011 vorgestellt. Habanos bezeichnet sie als von milder bis mittlerer Stärke, sehr aromatisch und von ausgewogenem Geschmack, und sieht in ihr eine Einladung zu einem kurzen Rauchgenuss.","vitolas":["Half Corona"],"wrapper":"Vuelta Abajo"}]',
  `gamme_zh` = '[{"name":"Sir Winston","color":"#8B6914","force":"Mild-Medium","story":"工厂规格（vitola de galera）为 Julieta No 2，cepo 47 x 178 毫米，habanos.com 如是说。该品牌的首款 Gran Reserva，即 Cosecha 2011，就以这一规格推出：5 000 个编号漆盒，每盒 15 支，用2011年采收、陈放五年的阿巴霍谷烟叶。Habanos 把该品牌描述为浓度轻至中等。","vitolas":["Sir Winston"],"wrapper":"Vuelta Abajo"},{"name":"Magnum","color":"#A0522D","force":"Mild-Medium","story":"Habanos 写道，Magnum 46 与 Magnum 50（2008年发布）自成一条产品线，另有独立的包装呈现；Magnum 54 于2016年进入常规系列。Magnum 46 长 5 5/8 英寸（143 毫米），cepo 46；Magnum 50 长 160 毫米，cepo 50；Magnum 54 长 4 3/4 英寸（120 毫米），cepo 54，据一家零售商和2017年的一份杂志（品牌方页面未给出其尺寸）。品牌方把 Magnum 系列归入浓度柔和至中等的 Habanos。","vitolas":["Magnum 46","Magnum 50","Magnum 54"],"wrapper":"Vuelta Abajo"},{"name":"Connoisseur","color":"#722F37","force":"Mild-Medium","story":"Habanos 提到一条“historic Connossieur Linea”（其新闻稿中的拼写）。No. 1 长 5 英寸（127 毫米），cepo 48，2013年10月仍在全面生产，品牌方已确认。Connossieur A（Genios，cepo 52 x 140 毫米，2013年10月9日）仅面向 Habanos Specialists 和 Casas del Habano；B（5 7/8 英寸，cepo 54）仅限 Casas del Habano 和 Habanos Specialists，据 Cigar Coop（2017年3月16日）于第十九届 Festival del Habano 推出，而行业媒体把它定在2018年；No. 2（cepo 51 x 134 毫米，据 Habanos 浓度柔和）于2020年11月24日在柏林发布，使该系列增至四种规格。","vitolas":["Connoisseur No.1","Connossieur A","Connossieur B","Connossieur No.2"],"wrapper":"Vuelta Abajo"},{"name":"Half Corona","color":"#8B4513","force":"Mild-Medium","story":"44 x 90 毫米的 vitola，于2011年2月在第十三届 Festival del Habano 上发布。Habanos 称其浓度柔和至中等，香气十足，口感均衡，并认为它是对一次短时吸食的邀请。","vitolas":["Half Corona"],"wrapper":"Vuelta Abajo"}]',
  `gamme_ar` = '[{"name":"Sir Winston","color":"#8B6914","force":"Mild-Medium","story":"Vitola de galera Julieta No 2، cepo 47 x 178 مم، بحسب habanos.com. وبهذا القياس أصدرت العلامة أولى Gran Reserva لها، Cosecha 2011: 5 000 علبة مطلية بالورنيش ومرقّمة، تحوي كل منها 15 سيجارًا، بأوراق من فويلتا أباخو حُصدت عام 2011 وعُتّقت خمس سنوات. وتصف Habanos العلامة بأنها خفيفة إلى متوسطة القوة.","vitolas":["Sir Winston"],"wrapper":"Vuelta Abajo"},{"name":"Magnum","color":"#A0522D","force":"Mild-Medium","story":"تكتب Habanos أن Magnum 46 وMagnum 50، الذي قُدِّم عام 2008، يشكّلان خطًّا مستقلًّا بتقديم متمايز؛ ويدخل Magnum 54 التشكيلة الاعتيادية عام 2016. قياس Magnum 46 هو 5 5/8 بوصة (143 مم) بـcepo 46؛ وقياس Magnum 50 هو 160 مم بـcepo 50؛ وقياس Magnum 54 هو 4 3/4 بوصة (120 مم) بـcepo 54، بحسب تاجر تجزئة ومجلة عام 2017 (لا تذكر صفحة الدار مقاساته). وتصنّف الدار خط Magnum ضمن Habanos ناعمة القوة إلى متوسطتها.","vitolas":["Magnum 46","Magnum 50","Magnum 54"],"wrapper":"Vuelta Abajo"},{"name":"Connoisseur","color":"#722F37","force":"Mild-Medium","story":"تتحدّث Habanos عن «historic Connossieur Linea» (هكذا يرد الإملاء في بياناتها). قياس No. 1 هو 5 بوصات (127 مم) بـcepo 48، وكان في إنتاج كامل في أكتوبر 2013، كما أكدت الدار. أما Connossieur A (Genios، cepo 52 x 140 مم، 9 أكتوبر 2013) فمخصّص لـHabanos Specialists وCasas del Habano وحدهم؛ ويُطلق B (5 7/8 بوصة، cepo 54)، الحصري لـCasas del Habano وHabanos Specialists، في XIX Festival del Habano بحسب Cigar Coop (16 مارس 2017)، في حين تؤرّخه الصحافة المتخصّصة بعام 2018؛ ويرفع No. 2 (cepo 51 x 134 مم، ناعم القوة بحسب Habanos)، الذي قُدِّم في برلين في 24 نوفمبر 2020، الخط إلى أربعة قياسات.","vitolas":["Connoisseur No.1","Connossieur A","Connossieur B","Connossieur No.2"],"wrapper":"Vuelta Abajo"},{"name":"Half Corona","color":"#8B4513","force":"Mild-Medium","story":"قياس 44 x 90 مم قُدِّم في الدورة الثالثة عشرة من Festival del Habano في فبراير 2011. تصفه Habanos بأنه ناعم القوة إلى متوسطها، عطري جدًّا ومتوازن المذاق، وترى فيه دعوة إلى تدخين قصير.","vitolas":["Half Corona"],"wrapper":"Vuelta Abajo"}]',
  `source` = IF(LOCATE(CAST('cigarsunlimited.co.uk « H.UPMANN Magnum 54 new size for H.Up' AS BINARY), CAST(`source` AS BINARY)) > 0, `source`, CONCAT(`source`, ' ; ', 'cigarsunlimited.co.uk « H.UPMANN Magnum 54 new size for H.Upmann » (détaillant, 25 janvier 2017 : 4 3/4 pouces, 120 mm, cepo 54) ; bespokeunit.com « H Upmann Magnum 54 Cigar Review » (8 mai 2017 : 4 3/4 x 54, Vuelta Abajo) ; cigar-coop.com « H. Upmann Connoisseur B to be Exclusive to La Casa del Habanos and Habanos Specialists » (16 mars 2017 : 5 7/8 x 54, XIXe Festival) ; en.wikipedia.org « H. Upmann » (Magnum 46 listé courant)')),
  `updated_at` = NOW()
 WHERE `name` = 'H. Upmann';

-- ── Montecristo ──
UPDATE `brands` SET
  `gamme` = '[{"name":"Línea Clásica","color":"#8B4513","force":"Medium-Full","story":"La ligne de base de la marque, de force moyenne à pleine selon habanos.com, en feuilles de la Vuelta Abajo, roulée à la main en tripe longue, du Montecristo A aux petits formats ; la marque a commencé avec cinq vitolas numérotées de 1 à 5. Le Montecristo A, un gran corona, mesure 9 1/4 pouces (235 mm) pour un cepo 47 ; le No. 1, un lonsdale, 6 1/2 pouces (165 mm) pour un cepo 42 ; le No. 2 est une pirámide (torpedo) de cepo 52 x 156 mm ; le No. 3, un corona, mesure 5 5/8 pouces (142 mm) pour un cepo 42 ; le No. 4, un petit corona (Mareva), cepo 42 x 129 mm ; le No. 5, un petit corona, 4 pouces pour un cepo 40. Les cotes du A et des No. 1, 3 et 5 viennent de la presse du métier et de détaillants, la page de marque de habanos.com ne les donnant pas. Un détaillant décrit des capes cubaines colorado, plus ou moins foncées, pour le A et les No. 1 et 3 ; habanos.com ne dit que l''origine des feuilles. Une Reserva (2007) rend hommage au No. 4 ; la Gran Reserva Cosecha 2005, présentée en 2011, est un No. 2. Hors ligne régulière, Habanos a présenté le 12 février 2015, dans sa nouvelle ligne Añejados, des Churchills de cepo 47 x 178 mm (galera Julieta No.2).","vitolas":["No.1","No.2","No.3","No.4","No.5","Montecristo A"],"wrapper":"Vuelta Abajo"},{"name":"Línea Edmundo","color":"#A0522D","force":"Medium-Full","story":"L''Edmundo (cepo 52 x 135 mm) a été présenté à Paris le 13 mai 2004, en feuilles de Vegas Finas de Primera de la Vuelta Abajo, de saveur moyenne à pleine ; la maison écrit qu''aucun nouveau format n''avait été créé dans sa catégorie depuis plus de trente ans. Le Petit Edmundo (cepo 52 x 110 mm) suit en 2007, le Double Edmundo et le Petit No. 2 (figurado, cepo 52 x 120 mm) en 2013.","vitolas":["Edmundo","Petit Edmundo","Double Edmundo"],"wrapper":"Vuelta Abajo"},{"name":"Línea 1935","color":"#722F37","force":"Full","story":"Annoncée par un communiqué du 27 mars 2018 et vendue en boîtes de 20, elle compte trois vitolas : Maltés (Sobresalientes, cepo 53 x 153 mm), Dumas (Prominente Corto, cepo 49 x 130 mm) et Leyenda (Maravillas No 2, cepo 55 x 165 mm, forme de la vitola spéciale 80 Aniversario de 2015). Habanos en fait le premier mélange de force pleine de la marque, plus fort que l''Open, en feuilles de la Vuelta Abajo sous une cape carmélite naturelle.","vitolas":["Maltés","Dumas","Leyenda"],"wrapper":"Carmélite naturelle"},{"name":"Línea Open","color":"#2E5E4E","force":"Medium","story":"Présentée au Festival del Habano de 2009 (communiqué du 11 juillet), elle compte quatre vitolas : Eagle (Geniales, cepo 54 x 150 mm), Regata (Forum, figurado, cepo 46 x 135 mm, qui suit de près la tradition du No. 2 dans une fumée plus fine, dit la maison), Master (cepo 50 x 124 mm) et Junior (Trabucos, cepo 38 x 110 mm). Habanos la décrit de force moyenne.","vitolas":[],"wrapper":"Vuelta Abajo"}]',
  `gamme_en` = '[{"name":"Línea Clásica","color":"#8B4513","force":"Medium-Full","story":"The brand''s base line, medium to full in strength according to habanos.com, made with Vuelta Abajo leaves and hand-rolled with longfiller, from the Montecristo A down to the small formats; the brand began with five vitolas numbered 1 to 5. The Montecristo A, a gran corona, measures 9 1/4 inches (235 mm) with a cepo 47; the No. 1, a lonsdale, 6 1/2 inches (165 mm) with a cepo 42; the No. 2 is a pirámide (torpedo) with a cepo 52 x 156 mm; the No. 3, a corona, measures 5 5/8 inches (142 mm) with a cepo 42; the No. 4, a petit corona (Mareva), has a cepo 42 x 129 mm; the No. 5, a petit corona, is 4 inches with a cepo 40. The dimensions of the A and of the No. 1, 3 and 5 come from the trade press and from retailers, the habanos.com brand page not giving them. A retailer describes Cuban colorado wrappers, more or less dark, for the A and the No. 1 and 3; habanos.com says only the origin of the leaves. A Reserva (2007) pays tribute to the No. 4; the Gran Reserva Cosecha 2005, presented in 2011, is a No. 2. Outside the regular line, Habanos presented on 12 February 2015, in its new Añejados line, Churchills with a cepo 47 x 178 mm (galera Julieta No.2).","vitolas":["No.1","No.2","No.3","No.4","No.5","Montecristo A"],"wrapper":"Vuelta Abajo"},{"name":"Línea Edmundo","color":"#A0522D","force":"Medium-Full","story":"The Edmundo (cepo 52 x 135 mm) was presented in Paris on 13 May 2004, in Vegas Finas de Primera leaves from the Vuelta Abajo, medium to full in flavour; the house writes that no new format had been created in its category for more than thirty years. The Petit Edmundo (cepo 52 x 110 mm) followed in 2007, the Double Edmundo and the Petit No. 2 (figurado, cepo 52 x 120 mm) in 2013.","vitolas":["Edmundo","Petit Edmundo","Double Edmundo"],"wrapper":"Vuelta Abajo"},{"name":"Línea 1935","color":"#722F37","force":"Full","story":"Announced by a press release of 27 March 2018 and sold in boxes of 20, it has three vitolas: Maltés (Sobresalientes, cepo 53 x 153 mm), Dumas (Prominente Corto, cepo 49 x 130 mm) and Leyenda (Maravillas No 2, cepo 55 x 165 mm, the shape of the 2015 special vitola 80 Aniversario). Habanos presents it as the brand''s first full-strength blend, stronger than the Open, in Vuelta Abajo leaves under a natural Carmelite wrapper.","vitolas":["Maltés","Dumas","Leyenda"],"wrapper":"Natural Carmelite"},{"name":"Línea Open","color":"#2E5E4E","force":"Medium","story":"Presented at the 2009 Festival del Habano (press release of 11 July), it has four vitolas: Eagle (Geniales, cepo 54 x 150 mm), Regata (Forum, figurado, cepo 46 x 135 mm, which follows the tradition of the No. 2 closely in a finer smoke, says the house), Master (cepo 50 x 124 mm) and Junior (Trabucos, cepo 38 x 110 mm). Habanos describes it as medium in strength.","vitolas":[],"wrapper":"Vuelta Abajo"}]',
  `gamme_es` = '[{"name":"Línea Clásica","color":"#8B4513","force":"Medium-Full","story":"La línea de base de la marca, de fuerza media a plena según habanos.com, de hojas de la Vuelta Abajo, liada a mano en tripa larga, del Montecristo A a los formatos pequeños; la marca empezó con cinco vitolas numeradas del 1 al 5. El Montecristo A, un gran corona, mide 9 1/4 pulgadas (235 mm) para un cepo 47; el No. 1, un lonsdale, 6 1/2 pulgadas (165 mm) para un cepo 42; el No. 2 es una pirámide (torpedo) de cepo 52 x 156 mm; el No. 3, un corona, mide 5 5/8 pulgadas (142 mm) para un cepo 42; el No. 4, un petit corona (Mareva), cepo 42 x 129 mm; el No. 5, un petit corona, 4 pulgadas para un cepo 40. Las medidas del A y de los No. 1, 3 y 5 proceden de la prensa del oficio y de minoristas, pues la página de marca de habanos.com no las da. Un minorista describe capas cubanas colorado, de tono más o menos oscuro, para el A y los No. 1 y 3; habanos.com solo dice el origen de las hojas. Una Reserva (2007) rinde homenaje al No. 4; la Gran Reserva Cosecha 2005, presentada en 2011, es un No. 2. Fuera de la línea regular, Habanos presentó el 12 de febrero de 2015, en su nueva línea Añejados, Churchills de cepo 47 x 178 mm (galera Julieta No.2).","vitolas":["No.1","No.2","No.3","No.4","No.5","Montecristo A"],"wrapper":"Vuelta Abajo"},{"name":"Línea Edmundo","color":"#A0522D","force":"Medium-Full","story":"El Edmundo (cepo 52 x 135 mm) se presentó en París el 13 de mayo de 2004, de hojas Vegas Finas de Primera de la Vuelta Abajo, de sabor medio a pleno; la casa escribe que no se había creado ningún formato nuevo en su categoría desde hacía más de treinta años. El Petit Edmundo (cepo 52 x 110 mm) lo sigue en 2007, el Double Edmundo y el Petit No. 2 (figurado, cepo 52 x 120 mm) en 2013.","vitolas":["Edmundo","Petit Edmundo","Double Edmundo"],"wrapper":"Vuelta Abajo"},{"name":"Línea 1935","color":"#722F37","force":"Full","story":"Anunciada por un comunicado del 27 de marzo de 2018 y vendida en cajas de 20, cuenta con tres vitolas: Maltés (Sobresalientes, cepo 53 x 153 mm), Dumas (Prominente Corto, cepo 49 x 130 mm) y Leyenda (Maravillas No 2, cepo 55 x 165 mm, forma de la vitola especial 80 Aniversario de 2015). Habanos la presenta como la primera mezcla de fuerza plena de la marca, más fuerte que la Open, de hojas de la Vuelta Abajo bajo una capa carmelita natural.","vitolas":["Maltés","Dumas","Leyenda"],"wrapper":"Carmelita natural"},{"name":"Línea Open","color":"#2E5E4E","force":"Medium","story":"Presentada en el Festival del Habano de 2009 (comunicado del 11 de julio), cuenta con cuatro vitolas: Eagle (Geniales, cepo 54 x 150 mm), Regata (Forum, figurado, cepo 46 x 135 mm, que sigue de cerca la tradición del No. 2 en una fumada más fina, dice la casa), Master (cepo 50 x 124 mm) y Junior (Trabucos, cepo 38 x 110 mm). Habanos la describe de fuerza media.","vitolas":[],"wrapper":"Vuelta Abajo"}]',
  `gamme_de` = '[{"name":"Línea Clásica","color":"#8B4513","force":"Medium-Full","story":"Die Basislinie der Marke, laut habanos.com von mittlerer bis voller Stärke, mit Blättern aus der Vuelta Abajo, von Hand als Langfüller gerollt, vom Montecristo A bis zu den kleinen Formaten; die Marke begann mit fünf Vitolas, nummeriert von 1 bis 5. Der Montecristo A (Gran Corona) misst 9 1/4 Zoll (235 mm) bei einem cepo 47; die No. 1, eine Lonsdale, 6 1/2 Zoll (165 mm) bei einem cepo 42; die No. 2 ist eine Pirámide (Torpedo) mit cepo 52 x 156 mm; die No. 3, eine Corona, misst 5 5/8 Zoll (142 mm) bei einem cepo 42; die No. 4, eine Petit Corona (Mareva), cepo 42 x 129 mm; die No. 5, eine Petit Corona, 4 Zoll bei einem cepo 40. Die Maße des A sowie der No. 1, 3 und 5 stammen aus der Fachpresse und von Einzelhändlern, da die Markenseite von habanos.com sie nicht angibt. Ein Einzelhändler beschreibt kubanische Colorado-Deckblätter, mehr oder weniger dunkel, für den A sowie die No. 1 und 3; habanos.com nennt nur die Herkunft der Blätter. Eine Reserva (2007) würdigt die No. 4; die Gran Reserva Cosecha 2005, 2011 vorgestellt, ist eine No. 2. Außerhalb der regulären Linie stellte Habanos am 12. Februar 2015 in seiner neuen Linie Añejados Churchills mit cepo 47 x 178 mm vor (galera Julieta No.2).","vitolas":["No.1","No.2","No.3","No.4","No.5","Montecristo A"],"wrapper":"Vuelta Abajo"},{"name":"Línea Edmundo","color":"#A0522D","force":"Medium-Full","story":"Die Edmundo (cepo 52 x 135 mm) wurde am 13. Mai 2004 in Paris vorgestellt, mit Blättern der Vegas Finas de Primera aus der Vuelta Abajo, von mittlerem bis vollem Geschmack; das Haus schreibt, seit mehr als dreißig Jahren sei in seiner Kategorie kein neues Format geschaffen worden. Die Petit Edmundo (cepo 52 x 110 mm) folgt 2007, die Double Edmundo und die Petit No. 2 (Figurado, cepo 52 x 120 mm) 2013.","vitolas":["Edmundo","Petit Edmundo","Double Edmundo"],"wrapper":"Vuelta Abajo"},{"name":"Línea 1935","color":"#722F37","force":"Full","story":"Durch eine Pressemitteilung vom 27. März 2018 angekündigt und in Kisten zu 20 verkauft, umfasst sie drei Vitolas: Maltés (Sobresalientes, cepo 53 x 153 mm), Dumas (Prominente Corto, cepo 49 x 130 mm) und Leyenda (Maravillas No 2, cepo 55 x 165 mm, Form der Sondervitola 80 Aniversario von 2015). Habanos stellt sie als die erste Mischung von voller Stärke der Marke vor, kräftiger als die Open, mit Blättern aus der Vuelta Abajo unter einem natürlichen Carmelita-Deckblatt.","vitolas":["Maltés","Dumas","Leyenda"],"wrapper":"Carmelita natur"},{"name":"Línea Open","color":"#2E5E4E","force":"Medium","story":"Beim Festival del Habano 2009 vorgestellt (Pressemitteilung vom 11. Juli), umfasst sie vier Vitolas: Eagle (Geniales, cepo 54 x 150 mm), Regata (Forum, Figurado, cepo 46 x 135 mm, die der Tradition der No. 2 eng folgt, in einem feineren Rauch, sagt das Haus), Master (cepo 50 x 124 mm) und Junior (Trabucos, cepo 38 x 110 mm). Habanos beschreibt sie als von mittlerer Stärke.","vitolas":[],"wrapper":"Vuelta Abajo"}]',
  `gamme_zh` = '[{"name":"Línea Clásica","color":"#8B4513","force":"Medium-Full","story":"该品牌的基础系列，据 habanos.com 浓度中等至浓郁，用阿巴霍谷的烟叶，手工卷制长茄芯，从 Montecristo A 到小规格；品牌起步时有五个编号为1至5的 vitola。Montecristo A 是 gran corona，长 9 1/4 英寸（235 毫米），cepo 47；No. 1 是 lonsdale，6 1/2 英寸（165 毫米），cepo 42；No. 2 是 pirámide（鱼雷形），cepo 52 x 156 毫米；No. 3 是 corona，长 5 5/8 英寸（142 毫米），cepo 42；No. 4 是 petit corona（Mareva），cepo 42 x 129 毫米；No. 5 是 petit corona，4 英寸，cepo 40。A 以及 No. 1、3、5 的尺寸来自行业媒体和零售商，habanos.com 的品牌页面并未给出。一家零售商描述 A 与 No. 1、3 用的是古巴 colorado 茄衣，颜色深浅不一；habanos.com 只说明了烟叶的产地。一款 Reserva（2007）向 No. 4 致敬；2011年发布的 Gran Reserva Cosecha 2005 是一支 No. 2。常规系列之外，Habanos 于2015年2月12日在其新的 Añejados 系列中推出了 cepo 47 x 178 毫米的 Churchills（galera Julieta No.2）。","vitolas":["No.1","No.2","No.3","No.4","No.5","Montecristo A"],"wrapper":"Vuelta Abajo"},{"name":"Línea Edmundo","color":"#A0522D","force":"Medium-Full","story":"Edmundo（cepo 52 x 135 毫米）于2004年5月13日在巴黎发布，用阿巴霍谷 Vegas Finas de Primera 的烟叶，风味中等至浓郁；品牌方写道，在其品类中已有三十多年没有创制新规格。Petit Edmundo（cepo 52 x 110 毫米）于2007年接续，Double Edmundo 和 Petit No. 2（figurado，cepo 52 x 120 毫米）于2013年推出。","vitolas":["Edmundo","Petit Edmundo","Double Edmundo"],"wrapper":"Vuelta Abajo"},{"name":"Línea 1935","color":"#722F37","force":"Full","story":"由2018年3月27日的新闻稿宣布，以每盒20支销售，共有三个 vitola：Maltés（Sobresalientes，cepo 53 x 153 毫米）、Dumas（Prominente Corto，cepo 49 x 130 毫米）和 Leyenda（Maravillas No 2，cepo 55 x 165 毫米，取自2015年特别 vitola 80 Aniversario 的形制）。Habanos 称它是该品牌首款浓度浓郁的配方，比 Open 更浓，用阿巴霍谷的烟叶，外覆天然 Carmelita 色茄衣。","vitolas":["Maltés","Dumas","Leyenda"],"wrapper":"Carmelita 天然色"},{"name":"Línea Open","color":"#2E5E4E","force":"Medium","story":"于2009年 Festival del Habano 上推出（7月11日新闻稿），共有四个 vitola：Eagle（Geniales，cepo 54 x 150 毫米）、Regata（Forum，figurado，cepo 46 x 135 毫米，据品牌方说，它紧随 No. 2 的传统，烟气更细腻）、Master（cepo 50 x 124 毫米）和 Junior（Trabucos，cepo 38 x 110 毫米）。Habanos 把它描述为浓度中等。","vitolas":[],"wrapper":"Vuelta Abajo"}]',
  `gamme_ar` = '[{"name":"Línea Clásica","color":"#8B4513","force":"Medium-Full","story":"الخط الأساسي للعلامة، متوسط القوة إلى كاملها بحسب habanos.com، من أوراق فويلتا أباخو، مُلفوف يدويًّا بحشوة طويلة، من Montecristo A إلى القياسات الصغيرة؛ وقد بدأت العلامة بخمسة قياسات مرقّمة من 1 إلى 5. قياس Montecristo A، وهو gran corona، 9 1/4 بوصة (235 مم) بـcepo 47؛ وNo. 1، وهو lonsdale، 6 1/2 بوصة (165 مم) بـcepo 42؛ وNo. 2 هو pirámide (torpedo) بـcepo 52 x 156 مم؛ وNo. 3، وهو corona، 5 5/8 بوصة (142 مم) بـcepo 42؛ وNo. 4 هو petit corona (Mareva) بـcepo 42 x 129 مم؛ وNo. 5، وهو petit corona، 4 بوصات بـcepo 40. وتأتي مقاسات A وNo. 1 و3 و5 من الصحافة المتخصّصة ومن تجار التجزئة، إذ لا تذكرها صفحة العلامة في habanos.com. ويصف تاجر تجزئة أغلفة كوبية colorado بدرجات متفاوتة من الدكنة، للـA وللـNo. 1 وNo. 3؛ ولا تذكر habanos.com سوى منشأ الأوراق. وتكرّم Reserva (2007) الـNo. 4؛ أما Gran Reserva Cosecha 2005، المقدَّمة عام 2011، فهي No. 2. وخارج الخط المنتظم قدّمت Habanos في 12 فبراير 2015، في خطها الجديد Añejados، Churchills بـcepo 47 x 178 مم (galera Julieta No.2).","vitolas":["No.1","No.2","No.3","No.4","No.5","Montecristo A"],"wrapper":"Vuelta Abajo"},{"name":"Línea Edmundo","color":"#A0522D","force":"Medium-Full","story":"قُدِّم Edmundo (cepo 52 x 135 مم) في باريس في 13 مايو 2004، بأوراق Vegas Finas de Primera من فويلتا أباخو، ونكهة متوسطة إلى كاملة؛ وتكتب الدار أنه لم يُستحدث أي قياس جديد في فئتها منذ ما يزيد على ثلاثين سنة. ثم يلحقه Petit Edmundo (cepo 52 x 110 مم) عام 2007، وDouble Edmundo وPetit No. 2 (figurado، cepo 52 x 120 مم) عام 2013.","vitolas":["Edmundo","Petit Edmundo","Double Edmundo"],"wrapper":"Vuelta Abajo"},{"name":"Línea 1935","color":"#722F37","force":"Full","story":"أُعلن عن هذا الخط ببيان في 27 مارس 2018 ويُباع في علب من 20، ويضم ثلاثة قياسات: Maltés (Sobresalientes، cepo 53 x 153 مم) وDumas (Prominente Corto، cepo 49 x 130 مم) وLeyenda (Maravillas No 2، cepo 55 x 165 مم، شكل القياس الخاص 80 Aniversario لعام 2015). وتجعل منه Habanos أول خلطة كاملة القوة في العلامة، أشدّ قوةً من Open، بأوراق من فويلتا أباخو تحت غلاف كارميليتا طبيعي.","vitolas":["Maltés","Dumas","Leyenda"],"wrapper":"كارميليتا طبيعي"},{"name":"Línea Open","color":"#2E5E4E","force":"Medium","story":"قُدِّم الخط في Festival del Habano عام 2009 (بيان 11 يوليو)، ويضم أربعة قياسات: Eagle (Geniales، cepo 54 x 150 مم) وRegata (Forum، figurado، cepo 46 x 135 مم، الذي يتبع تقليد No. 2 عن كثب بتدخين أرقّ، بحسب الدار) وMaster (cepo 50 x 124 مم) وJunior (Trabucos، cepo 38 x 110 مم). وتصفه Habanos بأنه متوسط القوة.","vitolas":[],"wrapper":"Vuelta Abajo"}]',
  `source` = IF(LOCATE(CAST('cigaraficionado.com « Montecristo A » (fiche de dégustation,' AS BINARY), CAST(`source` AS BINARY)) > 0, `source`, CONCAT(`source`, ' ; ', 'cigaraficionado.com « Montecristo A » (fiche de dégustation, 20 février 2007 : 9 1/4 x 47, Cuba), « Montecristo No. 1 » (6 1/2 x 42), « Montecristo No. 3 » (5 5/8 x 42), « Montecristo No. 5 » (4 x 40) et « 9 Things You Need to Know About Montecristo » (6 février 2019 : A de 9 1/4 pouces) ; cigarslover.com « Montecristo A » (détaillant, 9 mai 2022 : 235 mm, gran corona, cape colorado), « Montecristo No. 1 » (42 x 165 mm), « Montecristo No. 3 » (42 x 142 mm) et « Montecristo Churchill Añejados » (6 juin 2015 : 47 x 178 mm, cape colorado) ; simplycigars.co.uk « Montecristo No. 1 » (détaillant, sans date : lonsdale 6 1/2 x 42) ; habanos.com « Habanos s.a. presents its new Línea of Habanos Añejados (Aged Habanos) » (12 février 2015 : Montecristo Churchills Añejados, galera Julieta No.2, cepo 47 x 178 mm)')),
  `updated_at` = NOW()
 WHERE `name` = 'Montecristo';

-- ── Trinidad ──
UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Habanos décrit une tripe et une sous-cape très parfumées et aromatiques, de saveur moyenne, en feuilles de la Vuelta Abajo, et classe la marque en force moyenne ; selon Wikipédia, Adriano Martínez dit le mélange proche de celui des vitolas Cohiba, sans la troisième fermentation en tonneau. En 2003, Habanos a élargi la gamme de trois vitolas, présentées à Londres le 10 novembre : Reyes (cepo 40 x 110 mm), Coloniales (cepo 44 x 132 mm) et Robustos Extra (cepo 50 x 155 mm) ; viennent ensuite les Robustos T en 2009 et, en 2019, les Esmeralda (cepo 53 x 145 mm) et Media Luna (cepo 50 x 115 mm), le Topes (cepo 56 x 125 mm) rejoignant alors la gamme régulière. Le Vigía (vitola de galera Torres, cepo 54 x 110 mm), présenté en avril 2014, comble selon Habanos le vide laissé par deux formats disparus de la marque ; le Topes avait paru d''abord en Edición Limitada en 2016.' AS BINARY), CAST(`history` AS BINARY)) > 0 AND LOCATE(CAST('Habanos décrit une tripe et une sous-cape très parfumées et aromatiques, de saveur moyenne, en feuilles de la Vuelta Abajo, et classe la marque en force moyenne ; selon Wikipédia, Adriano Martínez dit le mélange proche de celui des vitolas Cohiba, sans la troisième fermentation en tonneau. En 2003, Habanos a élargi la gamme de trois vitolas, présentées à Londres le 10 novembre : Reyes (cepo 40 x 110 mm), Coloniales (cepo 44 x 132 mm) et Robustos Extra (cepo 50 x 155 mm) ; viennent ensuite les Robustos T en 2009 et, en 2019, les Esmeralda (cepo 53 x 145 mm) et Media Luna (cepo 50 x 115 mm), le Topes (cepo 56 x 125 mm) rejoignant alors la gamme régulière. Le Vigía (vitola de galera Torres, cepo 54 x 110 mm), présenté en avril 2014, comble selon Habanos le vide laissé par deux formats disparus de la marque ; le Topes avait paru d''abord en Edición Limitada en 2016. En février 2024, pour les 55 ans de la marque, les Robustos Extra, arrêtés auparavant selon la presse du métier, sont revenus en production régulière (6 1/8 pouces x cepo 50, boîtes de 12 et de 3, dit la presse du métier le 26 février 2024) ; Prensa Latina écrit le 27 février 2024 qu''ils élargissent le portefeuille standard.' AS BINARY), CAST(`history` AS BINARY)) = 0, REPLACE(`history`, 'Habanos décrit une tripe et une sous-cape très parfumées et aromatiques, de saveur moyenne, en feuilles de la Vuelta Abajo, et classe la marque en force moyenne ; selon Wikipédia, Adriano Martínez dit le mélange proche de celui des vitolas Cohiba, sans la troisième fermentation en tonneau. En 2003, Habanos a élargi la gamme de trois vitolas, présentées à Londres le 10 novembre : Reyes (cepo 40 x 110 mm), Coloniales (cepo 44 x 132 mm) et Robustos Extra (cepo 50 x 155 mm) ; viennent ensuite les Robustos T en 2009 et, en 2019, les Esmeralda (cepo 53 x 145 mm) et Media Luna (cepo 50 x 115 mm), le Topes (cepo 56 x 125 mm) rejoignant alors la gamme régulière. Le Vigía (vitola de galera Torres, cepo 54 x 110 mm), présenté en avril 2014, comble selon Habanos le vide laissé par deux formats disparus de la marque ; le Topes avait paru d''abord en Edición Limitada en 2016.', 'Habanos décrit une tripe et une sous-cape très parfumées et aromatiques, de saveur moyenne, en feuilles de la Vuelta Abajo, et classe la marque en force moyenne ; selon Wikipédia, Adriano Martínez dit le mélange proche de celui des vitolas Cohiba, sans la troisième fermentation en tonneau. En 2003, Habanos a élargi la gamme de trois vitolas, présentées à Londres le 10 novembre : Reyes (cepo 40 x 110 mm), Coloniales (cepo 44 x 132 mm) et Robustos Extra (cepo 50 x 155 mm) ; viennent ensuite les Robustos T en 2009 et, en 2019, les Esmeralda (cepo 53 x 145 mm) et Media Luna (cepo 50 x 115 mm), le Topes (cepo 56 x 125 mm) rejoignant alors la gamme régulière. Le Vigía (vitola de galera Torres, cepo 54 x 110 mm), présenté en avril 2014, comble selon Habanos le vide laissé par deux formats disparus de la marque ; le Topes avait paru d''abord en Edición Limitada en 2016. En février 2024, pour les 55 ans de la marque, les Robustos Extra, arrêtés auparavant selon la presse du métier, sont revenus en production régulière (6 1/8 pouces x cepo 50, boîtes de 12 et de 3, dit la presse du métier le 26 février 2024) ; Prensa Latina écrit le 27 février 2024 qu''ils élargissent le portefeuille standard.'), `history`),
  `history_en` = IF(LOCATE(CAST('Habanos describes a filler and a binder that are very fragrant and aromatic, of medium flavour, in Vuelta Abajo leaves, and classes the brand as medium in strength; according to Wikipedia, Adriano Martínez says the blend is close to that of the Cohiba vitolas, without the third fermentation in a barrel. In 2003 Habanos widened the range by three vitolas, presented in London on 10 November: Reyes (ring gauge 40 x 110 mm), Coloniales (ring gauge 44 x 132 mm) and Robustos Extra (ring gauge 50 x 155 mm); the Robustos T follow in 2009 and, in 2019, the Esmeralda (ring gauge 53 x 145 mm) and Media Luna (ring gauge 50 x 115 mm), the Topes (ring gauge 56 x 125 mm) then joining the regular range. The Vigía (vitola de galera Torres, ring gauge 54 x 110 mm), presented in April 2014, fills according to Habanos the gap left by two formats that disappeared from the brand; the Topes had first appeared as an Edición Limitada in 2016.' AS BINARY), CAST(`history_en` AS BINARY)) > 0 AND LOCATE(CAST('Habanos describes a filler and a binder that are very fragrant and aromatic, of medium flavour, in Vuelta Abajo leaves, and classes the brand as medium in strength; according to Wikipedia, Adriano Martínez says the blend is close to that of the Cohiba vitolas, without the third fermentation in a barrel. In 2003 Habanos widened the range by three vitolas, presented in London on 10 November: Reyes (ring gauge 40 x 110 mm), Coloniales (ring gauge 44 x 132 mm) and Robustos Extra (ring gauge 50 x 155 mm); the Robustos T follow in 2009 and, in 2019, the Esmeralda (ring gauge 53 x 145 mm) and Media Luna (ring gauge 50 x 115 mm), the Topes (ring gauge 56 x 125 mm) then joining the regular range. The Vigía (vitola de galera Torres, ring gauge 54 x 110 mm), presented in April 2014, fills according to Habanos the gap left by two formats that disappeared from the brand; the Topes had first appeared as an Edición Limitada in 2016. In February 2024, for the brand''s 55 years, the Robustos Extra, discontinued earlier according to the trade press, returned to regular production (6 1/8 inches x cepo 50, boxes of 12 and of 3, says the trade press on 26 February 2024); Prensa Latina writes on 27 February 2024 that they widen the standard portfolio.' AS BINARY), CAST(`history_en` AS BINARY)) = 0, REPLACE(`history_en`, 'Habanos describes a filler and a binder that are very fragrant and aromatic, of medium flavour, in Vuelta Abajo leaves, and classes the brand as medium in strength; according to Wikipedia, Adriano Martínez says the blend is close to that of the Cohiba vitolas, without the third fermentation in a barrel. In 2003 Habanos widened the range by three vitolas, presented in London on 10 November: Reyes (ring gauge 40 x 110 mm), Coloniales (ring gauge 44 x 132 mm) and Robustos Extra (ring gauge 50 x 155 mm); the Robustos T follow in 2009 and, in 2019, the Esmeralda (ring gauge 53 x 145 mm) and Media Luna (ring gauge 50 x 115 mm), the Topes (ring gauge 56 x 125 mm) then joining the regular range. The Vigía (vitola de galera Torres, ring gauge 54 x 110 mm), presented in April 2014, fills according to Habanos the gap left by two formats that disappeared from the brand; the Topes had first appeared as an Edición Limitada in 2016.', 'Habanos describes a filler and a binder that are very fragrant and aromatic, of medium flavour, in Vuelta Abajo leaves, and classes the brand as medium in strength; according to Wikipedia, Adriano Martínez says the blend is close to that of the Cohiba vitolas, without the third fermentation in a barrel. In 2003 Habanos widened the range by three vitolas, presented in London on 10 November: Reyes (ring gauge 40 x 110 mm), Coloniales (ring gauge 44 x 132 mm) and Robustos Extra (ring gauge 50 x 155 mm); the Robustos T follow in 2009 and, in 2019, the Esmeralda (ring gauge 53 x 145 mm) and Media Luna (ring gauge 50 x 115 mm), the Topes (ring gauge 56 x 125 mm) then joining the regular range. The Vigía (vitola de galera Torres, ring gauge 54 x 110 mm), presented in April 2014, fills according to Habanos the gap left by two formats that disappeared from the brand; the Topes had first appeared as an Edición Limitada in 2016. In February 2024, for the brand''s 55 years, the Robustos Extra, discontinued earlier according to the trade press, returned to regular production (6 1/8 inches x cepo 50, boxes of 12 and of 3, says the trade press on 26 February 2024); Prensa Latina writes on 27 February 2024 that they widen the standard portfolio.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('Habanos describe una tripa y una capote muy perfumadas y aromáticas, de sabor medio, en hojas de la Vuelta Abajo, y clasifica la marca en fuerza media; según Wikipedia, Adriano Martínez dice que la mezcla es parecida a la de las vitolas Cohiba, sin la tercera fermentación en barril. En 2003, Habanos amplió la gama con tres vitolas, presentadas en Londres el 10 de noviembre: Reyes (cepo 40 x 110 mm), Coloniales (cepo 44 x 132 mm) y Robustos Extra (cepo 50 x 155 mm); vienen después los Robustos T en 2009 y, en 2019, los Esmeralda (cepo 53 x 145 mm) y Media Luna (cepo 50 x 115 mm), con lo que el Topes (cepo 56 x 125 mm) pasa a la gama regular. El Vigía (vitola de galera Torres, cepo 54 x 110 mm), presentado en abril de 2014, llena según Habanos el vacío dejado por dos formatos desaparecidos de la marca; el Topes había salido primero como Edición Limitada en 2016.' AS BINARY), CAST(`history_es` AS BINARY)) > 0 AND LOCATE(CAST('Habanos describe una tripa y una capote muy perfumadas y aromáticas, de sabor medio, en hojas de la Vuelta Abajo, y clasifica la marca en fuerza media; según Wikipedia, Adriano Martínez dice que la mezcla es parecida a la de las vitolas Cohiba, sin la tercera fermentación en barril. En 2003, Habanos amplió la gama con tres vitolas, presentadas en Londres el 10 de noviembre: Reyes (cepo 40 x 110 mm), Coloniales (cepo 44 x 132 mm) y Robustos Extra (cepo 50 x 155 mm); vienen después los Robustos T en 2009 y, en 2019, los Esmeralda (cepo 53 x 145 mm) y Media Luna (cepo 50 x 115 mm), con lo que el Topes (cepo 56 x 125 mm) pasa a la gama regular. El Vigía (vitola de galera Torres, cepo 54 x 110 mm), presentado en abril de 2014, llena según Habanos el vacío dejado por dos formatos desaparecidos de la marca; el Topes había salido primero como Edición Limitada en 2016. En febrero de 2024, por los 55 años de la marca, los Robustos Extra, retirados antes según la prensa del oficio, volvieron a la producción regular (6 1/8 pulgadas x cepo 50, cajas de 12 y de 3, dice la prensa del oficio el 26 de febrero de 2024); Prensa Latina escribe el 27 de febrero de 2024 que amplían el portafolio estándar.' AS BINARY), CAST(`history_es` AS BINARY)) = 0, REPLACE(`history_es`, 'Habanos describe una tripa y una capote muy perfumadas y aromáticas, de sabor medio, en hojas de la Vuelta Abajo, y clasifica la marca en fuerza media; según Wikipedia, Adriano Martínez dice que la mezcla es parecida a la de las vitolas Cohiba, sin la tercera fermentación en barril. En 2003, Habanos amplió la gama con tres vitolas, presentadas en Londres el 10 de noviembre: Reyes (cepo 40 x 110 mm), Coloniales (cepo 44 x 132 mm) y Robustos Extra (cepo 50 x 155 mm); vienen después los Robustos T en 2009 y, en 2019, los Esmeralda (cepo 53 x 145 mm) y Media Luna (cepo 50 x 115 mm), con lo que el Topes (cepo 56 x 125 mm) pasa a la gama regular. El Vigía (vitola de galera Torres, cepo 54 x 110 mm), presentado en abril de 2014, llena según Habanos el vacío dejado por dos formatos desaparecidos de la marca; el Topes había salido primero como Edición Limitada en 2016.', 'Habanos describe una tripa y una capote muy perfumadas y aromáticas, de sabor medio, en hojas de la Vuelta Abajo, y clasifica la marca en fuerza media; según Wikipedia, Adriano Martínez dice que la mezcla es parecida a la de las vitolas Cohiba, sin la tercera fermentación en barril. En 2003, Habanos amplió la gama con tres vitolas, presentadas en Londres el 10 de noviembre: Reyes (cepo 40 x 110 mm), Coloniales (cepo 44 x 132 mm) y Robustos Extra (cepo 50 x 155 mm); vienen después los Robustos T en 2009 y, en 2019, los Esmeralda (cepo 53 x 145 mm) y Media Luna (cepo 50 x 115 mm), con lo que el Topes (cepo 56 x 125 mm) pasa a la gama regular. El Vigía (vitola de galera Torres, cepo 54 x 110 mm), presentado en abril de 2014, llena según Habanos el vacío dejado por dos formatos desaparecidos de la marca; el Topes había salido primero como Edición Limitada en 2016. En febrero de 2024, por los 55 años de la marca, los Robustos Extra, retirados antes según la prensa del oficio, volvieron a la producción regular (6 1/8 pulgadas x cepo 50, cajas de 12 y de 3, dice la prensa del oficio el 26 de febrero de 2024); Prensa Latina escribe el 27 de febrero de 2024 que amplían el portafolio estándar.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Habanos beschreibt eine sehr duftende und aromatische Einlage und ein ebensolches Umblatt, von mittlerem Geschmack, aus Blättern der Vuelta Abajo, und stuft die Marke in mittlerer Stärke ein; laut Wikipedia sagt Adriano Martínez, die Mischung sei der der Cohiba-Vitolas nahe, ohne die dritte Fermentation im Fass. 2003 erweiterte Habanos die Reihe um drei Vitolas, die am 10. November in London vorgestellt wurden: Reyes (Ringmaß 40 x 110 mm), Coloniales (Ringmaß 44 x 132 mm) und Robustos Extra (Ringmaß 50 x 155 mm); es folgen die Robustos T 2009 und 2019 die Esmeralda (Ringmaß 53 x 145 mm) und Media Luna (Ringmaß 50 x 115 mm), wobei die Topes (Ringmaß 56 x 125 mm) damals in die reguläre Reihe aufrückte. Die Vigía (Vitola de galera Torres, Ringmaß 54 x 110 mm), im April 2014 vorgestellt, schließt laut Habanos die Lücke, die zwei aus der Marke verschwundene Formate hinterlassen hatten; die Topes war 2016 zunächst als Edición Limitada erschienen.' AS BINARY), CAST(`history_de` AS BINARY)) > 0 AND LOCATE(CAST('Habanos beschreibt eine sehr duftende und aromatische Einlage und ein ebensolches Umblatt, von mittlerem Geschmack, aus Blättern der Vuelta Abajo, und stuft die Marke in mittlerer Stärke ein; laut Wikipedia sagt Adriano Martínez, die Mischung sei der der Cohiba-Vitolas nahe, ohne die dritte Fermentation im Fass. 2003 erweiterte Habanos die Reihe um drei Vitolas, die am 10. November in London vorgestellt wurden: Reyes (Ringmaß 40 x 110 mm), Coloniales (Ringmaß 44 x 132 mm) und Robustos Extra (Ringmaß 50 x 155 mm); es folgen die Robustos T 2009 und 2019 die Esmeralda (Ringmaß 53 x 145 mm) und Media Luna (Ringmaß 50 x 115 mm), wobei die Topes (Ringmaß 56 x 125 mm) damals in die reguläre Reihe aufrückte. Die Vigía (Vitola de galera Torres, Ringmaß 54 x 110 mm), im April 2014 vorgestellt, schließt laut Habanos die Lücke, die zwei aus der Marke verschwundene Formate hinterlassen hatten; die Topes war 2016 zunächst als Edición Limitada erschienen. Im Februar 2024, zum 55-jährigen Bestehen der Marke, kehrten die Robustos Extra, zuvor laut Fachpresse eingestellt, in die reguläre Produktion zurück (6 1/8 Zoll x cepo 50, Kisten zu 12 und zu 3, sagt die Fachpresse am 26. Februar 2024); Prensa Latina schreibt am 27. Februar 2024, sie erweiterten das Standardportfolio.' AS BINARY), CAST(`history_de` AS BINARY)) = 0, REPLACE(`history_de`, 'Habanos beschreibt eine sehr duftende und aromatische Einlage und ein ebensolches Umblatt, von mittlerem Geschmack, aus Blättern der Vuelta Abajo, und stuft die Marke in mittlerer Stärke ein; laut Wikipedia sagt Adriano Martínez, die Mischung sei der der Cohiba-Vitolas nahe, ohne die dritte Fermentation im Fass. 2003 erweiterte Habanos die Reihe um drei Vitolas, die am 10. November in London vorgestellt wurden: Reyes (Ringmaß 40 x 110 mm), Coloniales (Ringmaß 44 x 132 mm) und Robustos Extra (Ringmaß 50 x 155 mm); es folgen die Robustos T 2009 und 2019 die Esmeralda (Ringmaß 53 x 145 mm) und Media Luna (Ringmaß 50 x 115 mm), wobei die Topes (Ringmaß 56 x 125 mm) damals in die reguläre Reihe aufrückte. Die Vigía (Vitola de galera Torres, Ringmaß 54 x 110 mm), im April 2014 vorgestellt, schließt laut Habanos die Lücke, die zwei aus der Marke verschwundene Formate hinterlassen hatten; die Topes war 2016 zunächst als Edición Limitada erschienen.', 'Habanos beschreibt eine sehr duftende und aromatische Einlage und ein ebensolches Umblatt, von mittlerem Geschmack, aus Blättern der Vuelta Abajo, und stuft die Marke in mittlerer Stärke ein; laut Wikipedia sagt Adriano Martínez, die Mischung sei der der Cohiba-Vitolas nahe, ohne die dritte Fermentation im Fass. 2003 erweiterte Habanos die Reihe um drei Vitolas, die am 10. November in London vorgestellt wurden: Reyes (Ringmaß 40 x 110 mm), Coloniales (Ringmaß 44 x 132 mm) und Robustos Extra (Ringmaß 50 x 155 mm); es folgen die Robustos T 2009 und 2019 die Esmeralda (Ringmaß 53 x 145 mm) und Media Luna (Ringmaß 50 x 115 mm), wobei die Topes (Ringmaß 56 x 125 mm) damals in die reguläre Reihe aufrückte. Die Vigía (Vitola de galera Torres, Ringmaß 54 x 110 mm), im April 2014 vorgestellt, schließt laut Habanos die Lücke, die zwei aus der Marke verschwundene Formate hinterlassen hatten; die Topes war 2016 zunächst als Edición Limitada erschienen. Im Februar 2024, zum 55-jährigen Bestehen der Marke, kehrten die Robustos Extra, zuvor laut Fachpresse eingestellt, in die reguläre Produktion zurück (6 1/8 Zoll x cepo 50, Kisten zu 12 und zu 3, sagt die Fachpresse am 26. Februar 2024); Prensa Latina schreibt am 27. Februar 2024, sie erweiterten das Standardportfolio.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('Habanos 描述其茄芯和茄套芳香馥郁、香气十足，口味中等，用的是 Vuelta Abajo 烟叶，并把这个品牌归为中等强度；据维基百科，Adriano Martínez 说其调配与 Cohiba 各规格相近，只是没有第三次木桶发酵。2003年，Habanos 将产品线增加了三个规格，于11月10日在伦敦推出：Reyes（环径 40 x 110 毫米）、Coloniales（环径 44 x 132 毫米）和 Robustos Extra（环径 50 x 155 毫米）；此后是2009年的 Robustos T，以及2019年的 Esmeralda（环径 53 x 145 毫米）和 Media Luna（环径 50 x 115 毫米），Topes（环径 56 x 125 毫米）也在这时并入常规系列。Vigía（galera 名称为 Torres，环径 54 x 110 毫米）于2014年4月推出，据 Habanos，它填补了该品牌两个已消失规格留下的空缺；Topes 曾于2016年先以 Edición Limitada 出现。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0 AND LOCATE(CAST('Habanos 描述其茄芯和茄套芳香馥郁、香气十足，口味中等，用的是 Vuelta Abajo 烟叶，并把这个品牌归为中等强度；据维基百科，Adriano Martínez 说其调配与 Cohiba 各规格相近，只是没有第三次木桶发酵。2003年，Habanos 将产品线增加了三个规格，于11月10日在伦敦推出：Reyes（环径 40 x 110 毫米）、Coloniales（环径 44 x 132 毫米）和 Robustos Extra（环径 50 x 155 毫米）；此后是2009年的 Robustos T，以及2019年的 Esmeralda（环径 53 x 145 毫米）和 Media Luna（环径 50 x 115 毫米），Topes（环径 56 x 125 毫米）也在这时并入常规系列。Vigía（galera 名称为 Torres，环径 54 x 110 毫米）于2014年4月推出，据 Habanos，它填补了该品牌两个已消失规格留下的空缺；Topes 曾于2016年先以 Edición Limitada 出现。2024年2月，为纪念品牌55周年，此前据行业媒体已停产的 Robustos Extra 恢复了常规生产（6 1/8 英寸 x cepo 50，12支装和3支装盒，行业媒体2024年2月26日称）；Prensa Latina 于2024年2月27日写道，它们扩大了标准产品组合。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0, REPLACE(`history_zh`, 'Habanos 描述其茄芯和茄套芳香馥郁、香气十足，口味中等，用的是 Vuelta Abajo 烟叶，并把这个品牌归为中等强度；据维基百科，Adriano Martínez 说其调配与 Cohiba 各规格相近，只是没有第三次木桶发酵。2003年，Habanos 将产品线增加了三个规格，于11月10日在伦敦推出：Reyes（环径 40 x 110 毫米）、Coloniales（环径 44 x 132 毫米）和 Robustos Extra（环径 50 x 155 毫米）；此后是2009年的 Robustos T，以及2019年的 Esmeralda（环径 53 x 145 毫米）和 Media Luna（环径 50 x 115 毫米），Topes（环径 56 x 125 毫米）也在这时并入常规系列。Vigía（galera 名称为 Torres，环径 54 x 110 毫米）于2014年4月推出，据 Habanos，它填补了该品牌两个已消失规格留下的空缺；Topes 曾于2016年先以 Edición Limitada 出现。', 'Habanos 描述其茄芯和茄套芳香馥郁、香气十足，口味中等，用的是 Vuelta Abajo 烟叶，并把这个品牌归为中等强度；据维基百科，Adriano Martínez 说其调配与 Cohiba 各规格相近，只是没有第三次木桶发酵。2003年，Habanos 将产品线增加了三个规格，于11月10日在伦敦推出：Reyes（环径 40 x 110 毫米）、Coloniales（环径 44 x 132 毫米）和 Robustos Extra（环径 50 x 155 毫米）；此后是2009年的 Robustos T，以及2019年的 Esmeralda（环径 53 x 145 毫米）和 Media Luna（环径 50 x 115 毫米），Topes（环径 56 x 125 毫米）也在这时并入常规系列。Vigía（galera 名称为 Torres，环径 54 x 110 毫米）于2014年4月推出，据 Habanos，它填补了该品牌两个已消失规格留下的空缺；Topes 曾于2016年先以 Edición Limitada 出现。2024年2月，为纪念品牌55周年，此前据行业媒体已停产的 Robustos Extra 恢复了常规生产（6 1/8 英寸 x cepo 50，12支装和3支装盒，行业媒体2024年2月26日称）；Prensa Latina 于2024年2月27日写道，它们扩大了标准产品组合。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('تصف Habanos حشوة وغلافًا داخليًّا شديدَي العطر والأريج، بنكهة متوسطة، من أوراق Vuelta Abajo، وتصنّف العلامة بقوة متوسطة؛ وبحسب ويكيبيديا يقول Adriano Martínez إنّ الخلطة قريبة من خلطة أقيسة Cohiba، من دون التخمير الثالث في البرميل. وفي 2003 وسّعت Habanos المجموعة بثلاثة أقيسة قُدّمت في لندن في 10 نوفمبر: Reyes (قياس حلقي 40 x 110 مم) وColoniales (قياس حلقي 44 x 132 مم) وRobustos Extra (قياس حلقي 50 x 155 مم)؛ ثم جاء Robustos T عام 2009، وفي 2019 جاء Esmeralda (قياس حلقي 53 x 145 مم) وMedia Luna (قياس حلقي 50 x 115 مم)، وانضمّ عندئذ Topes (قياس حلقي 56 x 125 مم) إلى المجموعة العادية. أما Vigía (vitola de galera باسم Torres، قياس حلقي 54 x 110 مم)، الذي قُدّم في أبريل 2014، فيسدّ بحسب Habanos الفراغ الذي خلّفه قياسان اختفيا من العلامة؛ وكان Topes قد ظهر أولًا بوصفه Edición Limitada عام 2016.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0 AND LOCATE(CAST('تصف Habanos حشوة وغلافًا داخليًّا شديدَي العطر والأريج، بنكهة متوسطة، من أوراق Vuelta Abajo، وتصنّف العلامة بقوة متوسطة؛ وبحسب ويكيبيديا يقول Adriano Martínez إنّ الخلطة قريبة من خلطة أقيسة Cohiba، من دون التخمير الثالث في البرميل. وفي 2003 وسّعت Habanos المجموعة بثلاثة أقيسة قُدّمت في لندن في 10 نوفمبر: Reyes (قياس حلقي 40 x 110 مم) وColoniales (قياس حلقي 44 x 132 مم) وRobustos Extra (قياس حلقي 50 x 155 مم)؛ ثم جاء Robustos T عام 2009، وفي 2019 جاء Esmeralda (قياس حلقي 53 x 145 مم) وMedia Luna (قياس حلقي 50 x 115 مم)، وانضمّ عندئذ Topes (قياس حلقي 56 x 125 مم) إلى المجموعة العادية. أما Vigía (vitola de galera باسم Torres، قياس حلقي 54 x 110 مم)، الذي قُدّم في أبريل 2014، فيسدّ بحسب Habanos الفراغ الذي خلّفه قياسان اختفيا من العلامة؛ وكان Topes قد ظهر أولًا بوصفه Edición Limitada عام 2016. وفي فبراير 2024، بمناسبة مرور 55 عامًا على العلامة، عاد Robustos Extra، الذي توقّف قبل ذلك بحسب الصحافة المتخصّصة، إلى الإنتاج المنتظم (6 1/8 بوصة x cepo 50، علب من 12 ومن 3، بحسب الصحافة المتخصّصة في 26 فبراير 2024)؛ وتكتب Prensa Latina في 27 فبراير 2024 أنّ هذه الأقيسة توسّع المحفظة القياسية.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0, REPLACE(`history_ar`, 'تصف Habanos حشوة وغلافًا داخليًّا شديدَي العطر والأريج، بنكهة متوسطة، من أوراق Vuelta Abajo، وتصنّف العلامة بقوة متوسطة؛ وبحسب ويكيبيديا يقول Adriano Martínez إنّ الخلطة قريبة من خلطة أقيسة Cohiba، من دون التخمير الثالث في البرميل. وفي 2003 وسّعت Habanos المجموعة بثلاثة أقيسة قُدّمت في لندن في 10 نوفمبر: Reyes (قياس حلقي 40 x 110 مم) وColoniales (قياس حلقي 44 x 132 مم) وRobustos Extra (قياس حلقي 50 x 155 مم)؛ ثم جاء Robustos T عام 2009، وفي 2019 جاء Esmeralda (قياس حلقي 53 x 145 مم) وMedia Luna (قياس حلقي 50 x 115 مم)، وانضمّ عندئذ Topes (قياس حلقي 56 x 125 مم) إلى المجموعة العادية. أما Vigía (vitola de galera باسم Torres، قياس حلقي 54 x 110 مم)، الذي قُدّم في أبريل 2014، فيسدّ بحسب Habanos الفراغ الذي خلّفه قياسان اختفيا من العلامة؛ وكان Topes قد ظهر أولًا بوصفه Edición Limitada عام 2016.', 'تصف Habanos حشوة وغلافًا داخليًّا شديدَي العطر والأريج، بنكهة متوسطة، من أوراق Vuelta Abajo، وتصنّف العلامة بقوة متوسطة؛ وبحسب ويكيبيديا يقول Adriano Martínez إنّ الخلطة قريبة من خلطة أقيسة Cohiba، من دون التخمير الثالث في البرميل. وفي 2003 وسّعت Habanos المجموعة بثلاثة أقيسة قُدّمت في لندن في 10 نوفمبر: Reyes (قياس حلقي 40 x 110 مم) وColoniales (قياس حلقي 44 x 132 مم) وRobustos Extra (قياس حلقي 50 x 155 مم)؛ ثم جاء Robustos T عام 2009، وفي 2019 جاء Esmeralda (قياس حلقي 53 x 145 مم) وMedia Luna (قياس حلقي 50 x 115 مم)، وانضمّ عندئذ Topes (قياس حلقي 56 x 125 مم) إلى المجموعة العادية. أما Vigía (vitola de galera باسم Torres، قياس حلقي 54 x 110 مم)، الذي قُدّم في أبريل 2014، فيسدّ بحسب Habanos الفراغ الذي خلّفه قياسان اختفيا من العلامة؛ وكان Topes قد ظهر أولًا بوصفه Edición Limitada عام 2016. وفي فبراير 2024، بمناسبة مرور 55 عامًا على العلامة، عاد Robustos Extra، الذي توقّف قبل ذلك بحسب الصحافة المتخصّصة، إلى الإنتاج المنتظم (6 1/8 بوصة x cepo 50، علب من 12 ومن 3، بحسب الصحافة المتخصّصة في 26 فبراير 2024)؛ وتكتب Prensa Latina في 27 فبراير 2024 أنّ هذه الأقيسة توسّع المحفظة القياسية.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Trinidad';

UPDATE `brands` SET
  `history` = IF(LOCATE(CAST('Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Habanos ne nomme pas la fabrique de Trinidad. La presse du métier écrit en 2011 que, à la fabrique Francisco Donatién de Pinar del Río (58 rouleurs), 90 % des cigares sont des Trinidad, marque déménagée d''El Laguito, à La Havane, et que le bâtiment est une ancienne prison transformée en fabrique de cigares dans les années 1960. Les dates du bâtiment divergent : un guide de voyage le dit construit comme prison en 1859 et la fabrique inaugurée en 1961 ; un détaillant britannique écrit prison construite en 1868 et convertie en fabrique en 1961. En octobre 2026, la page « The Habanos Brands Academia » de habanos.com range Trinidad parmi les cinq marques de valeur d''un portefeuille de 27 marques, avec Bolívar, Punch, Quai d''Orsay et Ramón Allones, après les six marques globales. La presse du métier avait annoncé le classement le 1er août 2019 : 21 marques de portefeuille et un groupe de quatre marques de haute valeur — Bolívar, Punch, Ramón Allones et Trinidad —, Quai d''Orsay figurant alors parmi les autres. La page officielle le dit : pendant plusieurs années Trinidad fut faite à El Laguito, la fabrique de Cohiba ; aujourd''hui elle est faite à Pinar del Río. La presse du métier écrivait en octobre 2003 que tous les Trinidad, nouvelles tailles comprises, seraient apparemment faits à El Laguito, et en 2011 que la marque avait été déménagée d''El Laguito à Pinar del Río : la date du transfert, entre ces deux dates, n''est pas établie.' AS BINARY), CAST(`history` AS BINARY)) > 0, REPLACE(`history`, 'Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Habanos ne nomme pas la fabrique de Trinidad. La presse du métier écrit en 2011 que, à la fabrique Francisco Donatién de Pinar del Río (58 rouleurs), 90 % des cigares sont des Trinidad, marque déménagée d''El Laguito, à La Havane, et que le bâtiment est une ancienne prison transformée en fabrique de cigares dans les années 1960. Les dates du bâtiment divergent : un guide de voyage le dit construit comme prison en 1859 et la fabrique inaugurée en 1961 ; un détaillant britannique écrit prison construite en 1868 et convertie en fabrique en 1961. En octobre 2026, la page « The Habanos Brands Academia » de habanos.com range Trinidad parmi les cinq marques de valeur d''un portefeuille de 27 marques, avec Bolívar, Punch, Quai d''Orsay et Ramón Allones, après les six marques globales. La presse du métier avait annoncé le classement le 1er août 2019 : 21 marques de portefeuille et un groupe de quatre marques de haute valeur — Bolívar, Punch, Ramón Allones et Trinidad —, Quai d''Orsay figurant alors parmi les autres. La page officielle le dit : pendant plusieurs années Trinidad fut faite à El Laguito, la fabrique de Cohiba ; aujourd''hui elle est faite à Pinar del Río. La presse du métier écrivait en octobre 2003 que tous les Trinidad, nouvelles tailles comprises, seraient apparemment faits à El Laguito, et en 2011 que la marque avait été déménagée d''El Laguito à Pinar del Río : la date du transfert, entre ces deux dates, n''est pas établie.', 'Où est-elle roulée ? À Cuba la question a une réponse à deux étages. Depuis 2002, chaque marque de Habanos a une fabrique mère, responsable du choix des feuilles et de l''assemblage, et ses cigares peuvent être roulés dans n''importe laquelle des quelques dizaines de fabriques de l''île, sous la supervision de la mère ; Habanos ne publie pas cette carte, la presse du métier la reconstitue. Sa page de marque ne nomme pas la fabrique de Trinidad, mais le communiqué de Habanos du 14 novembre 2017 sur la Trinidad La Trova écrit que ces cigares sont faits aujourd''hui à la fabrique Francisco Donatién de Pinar del Río, que la presse du métier (15 novembre 2017) dit aussi connue comme la fabrique Vegueros. La presse du métier écrit en 2011 que, à la fabrique Francisco Donatién de Pinar del Río (58 rouleurs), 90 % des cigares sont des Trinidad, marque déménagée d''El Laguito, à La Havane, et que le bâtiment est une ancienne prison transformée en fabrique de cigares dans les années 1960. Les dates du bâtiment divergent : un guide de voyage le dit construit comme prison en 1859 et la fabrique inaugurée en 1961 ; un détaillant britannique écrit prison construite en 1868 et convertie en fabrique en 1961. En octobre 2026, la page « The Habanos Brands Academia » de habanos.com range Trinidad parmi les cinq marques de valeur d''un portefeuille de 27 marques, avec Bolívar, Punch, Quai d''Orsay et Ramón Allones, après les six marques globales. La presse du métier avait annoncé le classement le 1er août 2019 : 21 marques de portefeuille et un groupe de quatre marques de haute valeur — Bolívar, Punch, Ramón Allones et Trinidad —, Quai d''Orsay figurant alors parmi les autres. La page officielle le dit : pendant plusieurs années Trinidad fut faite à El Laguito, la fabrique de Cohiba ; aujourd''hui elle est faite à Pinar del Río. La presse du métier écrivait en octobre 2003 que tous les Trinidad, nouvelles tailles comprises, seraient apparemment faits à El Laguito, et en 2011 que la marque avait été déménagée d''El Laguito à Pinar del Río. Un détaillant britannique écrit qu''en 2004, devant une demande croissante, la production a été transférée à Pinar del Río ; aucune autre page lue ne date le transfert, qui reste établi seulement comme postérieur à octobre 2003 et antérieur à 2011.'), `history`),
  `history_en` = IF(LOCATE(CAST('Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Habanos does not name the factory of Trinidad. The trade press writes in 2011 that, at the Francisco Donatién factory in Pinar del Río (58 rollers), 90% of the cigars are Trinidad, a brand moved from El Laguito, in Havana, and that the building is a former prison converted into a cigar factory in the 1960s. The dates of the building diverge: a travel guide says it was built as a prison in 1859 and the factory inaugurated in 1961; a British retailer writes that the prison was built in 1868 and converted into a factory in 1961. In October 2026 the page “The Habanos Brands Academia” on habanos.com places Trinidad among the five value brands of a portfolio of 27 brands, with Bolívar, Punch, Quai d''Orsay and Ramón Allones, after the six global brands. The trade press had announced the classification on 1 August 2019: 21 portfolio brands and a group of four high-value brands (Bolívar, Punch, Ramón Allones and Trinidad), Quai d''Orsay then being among the others. The official page says it: for several years Trinidad was made at El Laguito, Cohiba''s factory; today it is made in Pinar del Río. The trade press wrote in October 2003 that all the Trinidad, new sizes included, would apparently be made at El Laguito, and in 2011 that the brand had been moved from El Laguito to Pinar del Río: the date of the transfer, between those two dates, is not established.' AS BINARY), CAST(`history_en` AS BINARY)) > 0, REPLACE(`history_en`, 'Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Habanos does not name the factory of Trinidad. The trade press writes in 2011 that, at the Francisco Donatién factory in Pinar del Río (58 rollers), 90% of the cigars are Trinidad, a brand moved from El Laguito, in Havana, and that the building is a former prison converted into a cigar factory in the 1960s. The dates of the building diverge: a travel guide says it was built as a prison in 1859 and the factory inaugurated in 1961; a British retailer writes that the prison was built in 1868 and converted into a factory in 1961. In October 2026 the page “The Habanos Brands Academia” on habanos.com places Trinidad among the five value brands of a portfolio of 27 brands, with Bolívar, Punch, Quai d''Orsay and Ramón Allones, after the six global brands. The trade press had announced the classification on 1 August 2019: 21 portfolio brands and a group of four high-value brands (Bolívar, Punch, Ramón Allones and Trinidad), Quai d''Orsay then being among the others. The official page says it: for several years Trinidad was made at El Laguito, Cohiba''s factory; today it is made in Pinar del Río. The trade press wrote in October 2003 that all the Trinidad, new sizes included, would apparently be made at El Laguito, and in 2011 that the brand had been moved from El Laguito to Pinar del Río: the date of the transfer, between those two dates, is not established.', 'Where is it rolled? In Cuba the question has a two-storey answer. Since 2002 each Habanos brand has had a mother factory, responsible for leaf selection and blend, and its cigars may be rolled in any of the island''s few dozen factories under the mother''s supervision; Habanos does not publish that map, the trade press reconstructs it. Its brand page does not name the factory of Trinidad, but the Habanos press release of 14 November 2017 on the Trinidad La Trova writes that these cigars are now made at the Francisco Donatién factory in Pinar del Río, which the trade press (15 November 2017) also says is known as the Vegueros factory. The trade press writes in 2011 that, at the Francisco Donatién factory in Pinar del Río (58 rollers), 90% of the cigars are Trinidad, a brand moved from El Laguito, in Havana, and that the building is a former prison converted into a cigar factory in the 1960s. The dates of the building diverge: a travel guide says it was built as a prison in 1859 and the factory inaugurated in 1961; a British retailer writes that the prison was built in 1868 and converted into a factory in 1961. In October 2026 the page “The Habanos Brands Academia” on habanos.com places Trinidad among the five value brands of a portfolio of 27 brands, with Bolívar, Punch, Quai d''Orsay and Ramón Allones, after the six global brands. The trade press had announced the classification on 1 August 2019: 21 portfolio brands and a group of four high-value brands (Bolívar, Punch, Ramón Allones and Trinidad), Quai d''Orsay then being among the others. The official page says it: for several years Trinidad was made at El Laguito, Cohiba''s factory; today it is made in Pinar del Río. The trade press wrote in October 2003 that all the Trinidad, new sizes included, would apparently be made at El Laguito, and in 2011 that the brand had been moved from El Laguito to Pinar del Río. A British retailer writes that in 2004, faced with growing demand, production was transferred to Pinar del Río; no other page read dates the transfer, which remains established only as later than October 2003 and earlier than 2011.'), `history_en`),
  `history_es` = IF(LOCATE(CAST('¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Habanos no nombra la fábrica de Trinidad. La prensa del oficio escribe en 2011 que, en la fábrica Francisco Donatién de Pinar del Río (58 torcedores), el 90 % de los puros son Trinidad, marca trasladada de El Laguito, en La Habana, y que el edificio es una antigua cárcel convertida en fábrica de puros en los años 1960. Las fechas del edificio divergen: una guía de viaje lo dice construido como cárcel en 1859 y la fábrica inaugurada en 1961; un minorista británico escribe que la cárcel se construyó en 1868 y se convirtió en fábrica en 1961. En octubre de 2026, la página «The Habanos Brands Academia» de habanos.com clasifica Trinidad entre las cinco marcas de valor de una cartera de 27 marcas, con Bolívar, Punch, Quai d''Orsay y Ramón Allones, después de las seis marcas globales. La prensa del oficio había anunciado la clasificación el 1 de agosto de 2019: 21 marcas de cartera y un grupo de cuatro marcas de alto valor (Bolívar, Punch, Ramón Allones y Trinidad), figurando entonces Quai d''Orsay entre las demás. La página oficial lo dice: durante varios años Trinidad se hizo en El Laguito, la fábrica de Cohiba; hoy se hace en Pinar del Río. La prensa del oficio escribía en octubre de 2003 que todos los Trinidad, incluidos los nuevos tamaños, se harían al parecer en El Laguito, y en 2011 que la marca había sido trasladada de El Laguito a Pinar del Río: la fecha del traslado, entre esas dos fechas, no está establecida.' AS BINARY), CAST(`history_es` AS BINARY)) > 0, REPLACE(`history_es`, '¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Habanos no nombra la fábrica de Trinidad. La prensa del oficio escribe en 2011 que, en la fábrica Francisco Donatién de Pinar del Río (58 torcedores), el 90 % de los puros son Trinidad, marca trasladada de El Laguito, en La Habana, y que el edificio es una antigua cárcel convertida en fábrica de puros en los años 1960. Las fechas del edificio divergen: una guía de viaje lo dice construido como cárcel en 1859 y la fábrica inaugurada en 1961; un minorista británico escribe que la cárcel se construyó en 1868 y se convirtió en fábrica en 1961. En octubre de 2026, la página «The Habanos Brands Academia» de habanos.com clasifica Trinidad entre las cinco marcas de valor de una cartera de 27 marcas, con Bolívar, Punch, Quai d''Orsay y Ramón Allones, después de las seis marcas globales. La prensa del oficio había anunciado la clasificación el 1 de agosto de 2019: 21 marcas de cartera y un grupo de cuatro marcas de alto valor (Bolívar, Punch, Ramón Allones y Trinidad), figurando entonces Quai d''Orsay entre las demás. La página oficial lo dice: durante varios años Trinidad se hizo en El Laguito, la fábrica de Cohiba; hoy se hace en Pinar del Río. La prensa del oficio escribía en octubre de 2003 que todos los Trinidad, incluidos los nuevos tamaños, se harían al parecer en El Laguito, y en 2011 que la marca había sido trasladada de El Laguito a Pinar del Río: la fecha del traslado, entre esas dos fechas, no está establecida.', '¿Dónde se lía? En Cuba la pregunta tiene una respuesta de dos pisos. Desde 2002 cada marca de Habanos tiene una fábrica madre, responsable de la selección de hojas y de la ligada, y sus puros pueden liarse en cualquiera de las pocas decenas de fábricas de la isla bajo supervisión de la madre; Habanos no publica ese mapa, la prensa del oficio lo reconstruye. Su página de marca no nombra la fábrica de Trinidad, pero el comunicado de Habanos del 14 de noviembre de 2017 sobre la Trinidad La Trova escribe que estos puros se hacen hoy en la fábrica Francisco Donatién de Pinar del Río, que la prensa del oficio (15 de noviembre de 2017) dice también conocida como la fábrica Vegueros. La prensa del oficio escribe en 2011 que, en la fábrica Francisco Donatién de Pinar del Río (58 torcedores), el 90 % de los puros son Trinidad, marca trasladada de El Laguito, en La Habana, y que el edificio es una antigua cárcel convertida en fábrica de puros en los años 1960. Las fechas del edificio divergen: una guía de viaje lo dice construido como cárcel en 1859 y la fábrica inaugurada en 1961; un minorista británico escribe que la cárcel se construyó en 1868 y se convirtió en fábrica en 1961. En octubre de 2026, la página «The Habanos Brands Academia» de habanos.com clasifica Trinidad entre las cinco marcas de valor de una cartera de 27 marcas, con Bolívar, Punch, Quai d''Orsay y Ramón Allones, después de las seis marcas globales. La prensa del oficio había anunciado la clasificación el 1 de agosto de 2019: 21 marcas de cartera y un grupo de cuatro marcas de alto valor (Bolívar, Punch, Ramón Allones y Trinidad), figurando entonces Quai d''Orsay entre las demás. La página oficial lo dice: durante varios años Trinidad se hizo en El Laguito, la fábrica de Cohiba; hoy se hace en Pinar del Río. La prensa del oficio escribía en octubre de 2003 que todos los Trinidad, incluidos los nuevos tamaños, se harían al parecer en El Laguito, y en 2011 que la marca había sido trasladada de El Laguito a Pinar del Río. Un minorista británico escribe que en 2004, ante una demanda creciente, la producción se trasladó a Pinar del Río; ninguna otra página leída fecha el traslado, que solo queda establecido como posterior a octubre de 2003 y anterior a 2011.'), `history_es`),
  `history_de` = IF(LOCATE(CAST('Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Habanos nennt die Fabrik von Trinidad nicht. Die Fachpresse schreibt 2011, dass in der Fabrik Francisco Donatién in Pinar del Río (58 Roller) 90 % der Zigarren Trinidad sind, eine Marke, die aus El Laguito in Havanna umgezogen ist, und dass das Gebäude ein ehemaliges Gefängnis ist, das in den 1960er Jahren in eine Zigarrenfabrik umgewandelt wurde. Die Daten des Gebäudes weichen voneinander ab: Ein Reiseführer sagt, dass es 1859 als Gefängnis gebaut und die Fabrik 1961 eingeweiht wurde; ein britischer Einzelhändler schreibt, dass das Gefängnis 1868 gebaut und 1961 in eine Fabrik umgewandelt wurde. Im Oktober 2026 führt die Seite „The Habanos Brands Academia“ auf habanos.com Trinidad unter den fünf Wertmarken eines Portfolios von 27 Marken auf, zusammen mit Bolívar, Punch, Quai d''Orsay und Ramón Allones, nach den sechs globalen Marken. Die Fachpresse hatte die Einteilung am 1. August 2019 angekündigt: 21 Portfoliomarken und eine Gruppe von vier Marken von hohem Wert (Bolívar, Punch, Ramón Allones und Trinidad), wobei Quai d''Orsay damals zu den übrigen zählte. Die offizielle Seite sagt es: Mehrere Jahre lang wurde Trinidad in El Laguito gemacht, der Fabrik von Cohiba; heute wird sie in Pinar del Río gemacht. Die Fachpresse schrieb im Oktober 2003, dass alle Trinidad, auch die neuen Größen, offenbar in El Laguito gemacht würden, und 2011, dass die Marke von El Laguito nach Pinar del Río verlegt worden war: Das Datum des Wechsels, zwischen diesen beiden Daten, ist nicht belegt.' AS BINARY), CAST(`history_de` AS BINARY)) > 0, REPLACE(`history_de`, 'Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Habanos nennt die Fabrik von Trinidad nicht. Die Fachpresse schreibt 2011, dass in der Fabrik Francisco Donatién in Pinar del Río (58 Roller) 90 % der Zigarren Trinidad sind, eine Marke, die aus El Laguito in Havanna umgezogen ist, und dass das Gebäude ein ehemaliges Gefängnis ist, das in den 1960er Jahren in eine Zigarrenfabrik umgewandelt wurde. Die Daten des Gebäudes weichen voneinander ab: Ein Reiseführer sagt, dass es 1859 als Gefängnis gebaut und die Fabrik 1961 eingeweiht wurde; ein britischer Einzelhändler schreibt, dass das Gefängnis 1868 gebaut und 1961 in eine Fabrik umgewandelt wurde. Im Oktober 2026 führt die Seite „The Habanos Brands Academia“ auf habanos.com Trinidad unter den fünf Wertmarken eines Portfolios von 27 Marken auf, zusammen mit Bolívar, Punch, Quai d''Orsay und Ramón Allones, nach den sechs globalen Marken. Die Fachpresse hatte die Einteilung am 1. August 2019 angekündigt: 21 Portfoliomarken und eine Gruppe von vier Marken von hohem Wert (Bolívar, Punch, Ramón Allones und Trinidad), wobei Quai d''Orsay damals zu den übrigen zählte. Die offizielle Seite sagt es: Mehrere Jahre lang wurde Trinidad in El Laguito gemacht, der Fabrik von Cohiba; heute wird sie in Pinar del Río gemacht. Die Fachpresse schrieb im Oktober 2003, dass alle Trinidad, auch die neuen Größen, offenbar in El Laguito gemacht würden, und 2011, dass die Marke von El Laguito nach Pinar del Río verlegt worden war: Das Datum des Wechsels, zwischen diesen beiden Daten, ist nicht belegt.', 'Wo wird sie gerollt? In Kuba hat die Frage eine zweistöckige Antwort. Seit 2002 hat jede Habanos-Marke eine Mutterfabrik, verantwortlich für Blattauswahl und Mischung, und ihre Zigarren dürfen in jeder der wenigen Dutzend Fabriken der Insel unter Aufsicht der Mutter gerollt werden; Habanos veröffentlicht diese Karte nicht, die Fachpresse rekonstruiert sie. Ihre Markenseite nennt die Fabrik von Trinidad nicht, aber die Habanos-Mitteilung vom 14. November 2017 zur Trinidad La Trova schreibt, dass diese Zigarren heute in der Fabrik Francisco Donatién in Pinar del Río gemacht werden, die laut Fachpresse (15. November 2017) auch als Fabrik Vegueros bekannt ist. Die Fachpresse schreibt 2011, dass in der Fabrik Francisco Donatién in Pinar del Río (58 Roller) 90 % der Zigarren Trinidad sind, eine Marke, die aus El Laguito in Havanna umgezogen ist, und dass das Gebäude ein ehemaliges Gefängnis ist, das in den 1960er Jahren in eine Zigarrenfabrik umgewandelt wurde. Die Daten des Gebäudes weichen voneinander ab: Ein Reiseführer sagt, dass es 1859 als Gefängnis gebaut und die Fabrik 1961 eingeweiht wurde; ein britischer Einzelhändler schreibt, dass das Gefängnis 1868 gebaut und 1961 in eine Fabrik umgewandelt wurde. Im Oktober 2026 führt die Seite „The Habanos Brands Academia“ auf habanos.com Trinidad unter den fünf Wertmarken eines Portfolios von 27 Marken auf, zusammen mit Bolívar, Punch, Quai d''Orsay und Ramón Allones, nach den sechs globalen Marken. Die Fachpresse hatte die Einteilung am 1. August 2019 angekündigt: 21 Portfoliomarken und eine Gruppe von vier Marken von hohem Wert (Bolívar, Punch, Ramón Allones und Trinidad), wobei Quai d''Orsay damals zu den übrigen zählte. Die offizielle Seite sagt es: Mehrere Jahre lang wurde Trinidad in El Laguito gemacht, der Fabrik von Cohiba; heute wird sie in Pinar del Río gemacht. Die Fachpresse schrieb im Oktober 2003, dass alle Trinidad, auch die neuen Größen, offenbar in El Laguito gemacht würden, und 2011, dass die Marke von El Laguito nach Pinar del Río verlegt worden war. Ein britischer Einzelhändler schreibt, dass 2004 angesichts wachsender Nachfrage die Produktion nach Pinar del Río verlegt wurde; keine andere gelesene Seite datiert den Wechsel, der nur als nach Oktober 2003 und vor 2011 liegend belegt ist.'), `history_de`),
  `history_zh` = IF(LOCATE(CAST('它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。Habanos 没有点出 Trinidad 的工厂。行业媒体2011年写道，在比那尔德里奥的 Francisco Donatién 工厂（58名卷茄师），90%的雪茄是 Trinidad，这个品牌是从哈瓦那的 El Laguito 搬来的，而这栋建筑是一座在1960年代改成雪茄厂的旧监狱。这栋建筑的年代说法不一：一本旅行指南说它于1859年建成监狱，1961年工厂启用；一家英国零售商则写道，监狱建于1868年，1961年改建为工厂。2026年10月，habanos.com 上的“The Habanos Brands Academia”页面把 Trinidad 列入由27个品牌组成的组合中的五个价值品牌，与 Bolívar、Punch、Quai d''Orsay 和 Ramón Allones 并列，排在六个全球品牌之后。行业媒体曾于2019年8月1日宣布这一归类：21个组合品牌，外加一组四个高价值品牌（Bolívar、Punch、Ramón Allones 和 Trinidad），当时 Quai d''Orsay 属于其余品牌之列。官方页面写明：Trinidad 曾有几年在 Cohiba 的工厂 El Laguito 制作，如今在比那尔德里奥制作。行业媒体2003年10月写道，所有 Trinidad，包括新尺寸，显然都将在 El Laguito 制作；2011年又写道，这个品牌已从 El Laguito 搬到比那尔德里奥：转移的日期介于这两个时间之间，尚未确定。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0, REPLACE(`history_zh`, '它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。Habanos 没有点出 Trinidad 的工厂。行业媒体2011年写道，在比那尔德里奥的 Francisco Donatién 工厂（58名卷茄师），90%的雪茄是 Trinidad，这个品牌是从哈瓦那的 El Laguito 搬来的，而这栋建筑是一座在1960年代改成雪茄厂的旧监狱。这栋建筑的年代说法不一：一本旅行指南说它于1859年建成监狱，1961年工厂启用；一家英国零售商则写道，监狱建于1868年，1961年改建为工厂。2026年10月，habanos.com 上的“The Habanos Brands Academia”页面把 Trinidad 列入由27个品牌组成的组合中的五个价值品牌，与 Bolívar、Punch、Quai d''Orsay 和 Ramón Allones 并列，排在六个全球品牌之后。行业媒体曾于2019年8月1日宣布这一归类：21个组合品牌，外加一组四个高价值品牌（Bolívar、Punch、Ramón Allones 和 Trinidad），当时 Quai d''Orsay 属于其余品牌之列。官方页面写明：Trinidad 曾有几年在 Cohiba 的工厂 El Laguito 制作，如今在比那尔德里奥制作。行业媒体2003年10月写道，所有 Trinidad，包括新尺寸，显然都将在 El Laguito 制作；2011年又写道，这个品牌已从 El Laguito 搬到比那尔德里奥：转移的日期介于这两个时间之间，尚未确定。', '它在哪里卷制？在古巴，这个问题的答案分两层。自2002年起，Habanos 的每个品牌都有一家母厂，负责选叶和配方，其雪茄可以在岛上几十家工厂中的任何一家、在母厂监督下卷制；Habanos 不公布这张图，由行业媒体拼出来。其品牌页面没有点出 Trinidad 的工厂，但 Habanos 2017年11月14日关于 Trinidad La Trova 的新闻稿写道，这些雪茄如今在比那尔德里奥的 Francisco Donatién 工厂制作，行业媒体（2017年11月15日）称该厂也叫 Vegueros 工厂。行业媒体2011年写道，在比那尔德里奥的 Francisco Donatién 工厂（58名卷茄师），90%的雪茄是 Trinidad，这个品牌是从哈瓦那的 El Laguito 搬来的，而这栋建筑是一座在1960年代改成雪茄厂的旧监狱。这栋建筑的年代说法不一：一本旅行指南说它于1859年建成监狱，1961年工厂启用；一家英国零售商则写道，监狱建于1868年，1961年改建为工厂。2026年10月，habanos.com 上的“The Habanos Brands Academia”页面把 Trinidad 列入由27个品牌组成的组合中的五个价值品牌，与 Bolívar、Punch、Quai d''Orsay 和 Ramón Allones 并列，排在六个全球品牌之后。行业媒体曾于2019年8月1日宣布这一归类：21个组合品牌，外加一组四个高价值品牌（Bolívar、Punch、Ramón Allones 和 Trinidad），当时 Quai d''Orsay 属于其余品牌之列。官方页面写明：Trinidad 曾有几年在 Cohiba 的工厂 El Laguito 制作，如今在比那尔德里奥制作。行业媒体2003年10月写道，所有 Trinidad，包括新尺寸，显然都将在 El Laguito 制作；2011年又写道，这个品牌已从 El Laguito 搬到比那尔德里奥。一家英国零售商写道，2004年面对不断增长的需求，生产转移到了比那尔德里奥；所读的其他页面均未给出转移日期，只能确定它晚于2003年10月、早于2011年。'), `history_zh`),
  `history_ar` = IF(LOCATE(CAST('أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. ولا تسمّي Habanos مصنع Trinidad. وتكتب الصحافة المتخصّصة عام 2011 أنّ 90% من السيجار في مصنع Francisco Donatién في بينار ديل ريو (58 لفّافًا) هو Trinidad، وهي علامة نُقلت من El Laguito في هافانا، وأنّ المبنى سجن سابق حُوّل إلى مصنع سيجار في عقد 1960. وتتباين تواريخ المبنى: يقول دليل سفر إنه بُني سجنًا عام 1859 وافتُتح المصنع عام 1961؛ ويكتب تاجر تجزئة بريطاني إنّ السجن بُني عام 1868 وحُوّل إلى مصنع عام 1961. وفي أكتوبر 2026 تدرج صفحة «The Habanos Brands Academia» على موقع habanos.com علامة Trinidad ضمن العلامات الخمس ذات القيمة من محفظة تضم 27 علامة، مع Bolívar وPunch وQuai d''Orsay وRamón Allones، بعد العلامات العالمية الست. وكانت الصحافة المتخصّصة قد أعلنت هذا التصنيف في 1 أغسطس 2019: 21 علامة في المحفظة ومجموعة من أربع علامات عالية القيمة (Bolívar وPunch وRamón Allones وTrinidad)، وكانت Quai d''Orsay آنذاك بين العلامات الأخرى. تقول الصفحة الرسمية ذلك: لسنوات عدّة صُنعت Trinidad في El Laguito، مصنع Cohiba؛ واليوم تُصنع في بينار ديل ريو. وكتبت الصحافة المتخصّصة في أكتوبر 2003 أنّ جميع سيجار Trinidad، بما فيها الأحجام الجديدة، ستُصنع على ما يبدو في El Laguito، وفي 2011 أنّ العلامة نُقلت من El Laguito إلى بينار ديل ريو: تاريخ النقل، الواقع بين هذين التاريخين، غير ثابت.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0, REPLACE(`history_ar`, 'أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. ولا تسمّي Habanos مصنع Trinidad. وتكتب الصحافة المتخصّصة عام 2011 أنّ 90% من السيجار في مصنع Francisco Donatién في بينار ديل ريو (58 لفّافًا) هو Trinidad، وهي علامة نُقلت من El Laguito في هافانا، وأنّ المبنى سجن سابق حُوّل إلى مصنع سيجار في عقد 1960. وتتباين تواريخ المبنى: يقول دليل سفر إنه بُني سجنًا عام 1859 وافتُتح المصنع عام 1961؛ ويكتب تاجر تجزئة بريطاني إنّ السجن بُني عام 1868 وحُوّل إلى مصنع عام 1961. وفي أكتوبر 2026 تدرج صفحة «The Habanos Brands Academia» على موقع habanos.com علامة Trinidad ضمن العلامات الخمس ذات القيمة من محفظة تضم 27 علامة، مع Bolívar وPunch وQuai d''Orsay وRamón Allones، بعد العلامات العالمية الست. وكانت الصحافة المتخصّصة قد أعلنت هذا التصنيف في 1 أغسطس 2019: 21 علامة في المحفظة ومجموعة من أربع علامات عالية القيمة (Bolívar وPunch وRamón Allones وTrinidad)، وكانت Quai d''Orsay آنذاك بين العلامات الأخرى. تقول الصفحة الرسمية ذلك: لسنوات عدّة صُنعت Trinidad في El Laguito، مصنع Cohiba؛ واليوم تُصنع في بينار ديل ريو. وكتبت الصحافة المتخصّصة في أكتوبر 2003 أنّ جميع سيجار Trinidad، بما فيها الأحجام الجديدة، ستُصنع على ما يبدو في El Laguito، وفي 2011 أنّ العلامة نُقلت من El Laguito إلى بينار ديل ريو: تاريخ النقل، الواقع بين هذين التاريخين، غير ثابت.', 'أين تُلفّ؟ في كوبا للسؤال جواب من طابقين. منذ 2002 لكلّ علامة من علامات Habanos مصنع أمّ، مسؤول عن اختيار الأوراق والخلطة، ويمكن أن يُلفّ سيجارها في أيّ من عشرات المصانع في الجزيرة تحت إشراف الأمّ؛ ولا تنشر Habanos هذه الخريطة، بل تعيد الصحافة المتخصّصة تركيبها. ولا تسمّي صفحة العلامة مصنع Trinidad، لكنّ بيان Habanos في 14 نوفمبر 2017 عن Trinidad La Trova يكتب أنّ هذا السيجار يُصنع اليوم في مصنع Francisco Donatién في بينار ديل ريو، وتقول الصحافة المتخصّصة (15 نوفمبر 2017) إنه يُعرف أيضًا باسم مصنع Vegueros. وتكتب الصحافة المتخصّصة عام 2011 أنّ 90% من السيجار في مصنع Francisco Donatién في بينار ديل ريو (58 لفّافًا) هو Trinidad، وهي علامة نُقلت من El Laguito في هافانا، وأنّ المبنى سجن سابق حُوّل إلى مصنع سيجار في عقد 1960. وتتباين تواريخ المبنى: يقول دليل سفر إنه بُني سجنًا عام 1859 وافتُتح المصنع عام 1961؛ ويكتب تاجر تجزئة بريطاني إنّ السجن بُني عام 1868 وحُوّل إلى مصنع عام 1961. وفي أكتوبر 2026 تدرج صفحة «The Habanos Brands Academia» على موقع habanos.com علامة Trinidad ضمن العلامات الخمس ذات القيمة من محفظة تضم 27 علامة، مع Bolívar وPunch وQuai d''Orsay وRamón Allones، بعد العلامات العالمية الست. وكانت الصحافة المتخصّصة قد أعلنت هذا التصنيف في 1 أغسطس 2019: 21 علامة في المحفظة ومجموعة من أربع علامات عالية القيمة (Bolívar وPunch وRamón Allones وTrinidad)، وكانت Quai d''Orsay آنذاك بين العلامات الأخرى. تقول الصفحة الرسمية ذلك: لسنوات عدّة صُنعت Trinidad في El Laguito، مصنع Cohiba؛ واليوم تُصنع في بينار ديل ريو. وكتبت الصحافة المتخصّصة في أكتوبر 2003 أنّ جميع سيجار Trinidad، بما فيها الأحجام الجديدة، ستُصنع على ما يبدو في El Laguito، وفي 2011 أنّ العلامة نُقلت من El Laguito إلى بينار ديل ريو. ويكتب تاجر تجزئة بريطاني أنّه في 2004، أمام طلب متزايد، نُقل الإنتاج إلى بينار ديل ريو؛ ولا تؤرّخ أي صفحة أخرى مقروءة النقل، الذي لا يثبت إلا بوصفه لاحقًا لأكتوبر 2003 وسابقًا لعام 2011.'), `history_ar`),
  `updated_at` = NOW()
 WHERE `name` = 'Trinidad';

UPDATE `brands` SET
  `factory` = 'Fabrique Francisco Donatién, Pinar del Río (communiqué Habanos de 2017), après des années à El Laguito, dit habanos.com ; transfert : 2004 selon un détaillant, non établi',
  `gamme` = '[{"name":"Fundadores","color":"#8B6914","force":"Medium","story":"Seule vitola de la marque à ses débuts, dit habanos.com, qui la donne de cepo 40 pour 192 mm de long (communiqué du 7 octobre 2003) ; elle reste alors dans la gamme, en coffrets vernis de 12 et 24 et en paquets de 5. La presse du métier la note en 7 1/2 pouces x 40 (2019). Habanos classe la marque en force moyenne.","vitolas":["Fundadores"],"wrapper":"Vuelta Abajo"},{"name":"Reyes","color":"#A0522D","force":"Medium","story":"Vitola de cepo 40 x 110 mm, présentée à Londres le 10 novembre 2003 avec les Coloniales et les Robustos Extra, en coffrets de 12 et 24 et en paquets de 5, dit habanos.com.","vitolas":["Reyes"],"wrapper":"Vuelta Abajo"},{"name":"Coloniales","color":"#8B4513","force":"Medium","story":"Vitola de cepo 44 x 132 mm, présentée en 2003 en même temps que les Reyes et les Robustos Extra, en coffrets de 12 et 24 et en paquets de 5, dit habanos.com.","vitolas":["Coloniales"],"wrapper":"Vuelta Abajo"},{"name":"Robustos Extra","color":"#722F37","force":"Medium","story":"Vitola de cepo 50 x 155 mm, présentée en 2003, en coffrets de 12 et 24 et en paquets de 3, dit habanos.com, dont la page de marque date aussi de 2009 les Robustos T (sans donner leurs cotes ; Wikipédia les liste à 4 7/8 pouces x 50). Les Robustos Extra, arrêtés auparavant selon la presse du métier, sont revenus en production régulière en février 2024 pour les 55 ans de la marque (6 1/8 pouces x cepo 50, boîtes de 12 et de 3, nouvelle présentation). Le statut actuel des Robustos T n''est établi par aucune page lue.","vitolas":["Robustos Extra","Robustos T"],"wrapper":"Vuelta Abajo"},{"name":"Vigía, Topes, Esmeralda et Media Luna","color":"#6B8E23","force":"Medium","story":"Vigía : vitola de galera Torres, cepo 54 (21,43 mm) x 110 mm, présentée en avril 2014. Topes : cepo 56 (22,23 mm) x 125 mm, Edición Limitada 2016 puis gamme régulière en 2019. Esmeralda (cepo 53 x 145 mm) et Media Luna (cepo 50 x 115 mm) : 2019. Toutes selon habanos.com, qui donne la marque en force moyenne.","vitolas":[],"wrapper":"Vuelta Abajo"}]',
  `gamme_en` = '[{"name":"Fundadores","color":"#8B6914","force":"Medium","story":"The brand''s only vitola at its start, says habanos.com, which gives it as ring gauge 40 and 192 mm long (press release of 7 October 2003); it then remains in the range, in varnished boxes of 12 and 24 and in packs of 5. The trade press notes it as 7 1/2 inches x 40 (2019). Habanos classes the brand as medium in strength.","vitolas":["Fundadores"],"wrapper":"Vuelta Abajo"},{"name":"Reyes","color":"#A0522D","force":"Medium","story":"A vitola of ring gauge 40 x 110 mm, presented in London on 10 November 2003 with the Coloniales and the Robustos Extra, in boxes of 12 and 24 and in packs of 5, says habanos.com.","vitolas":["Reyes"],"wrapper":"Vuelta Abajo"},{"name":"Coloniales","color":"#8B4513","force":"Medium","story":"A vitola of ring gauge 44 x 132 mm, presented in 2003 at the same time as the Reyes and the Robustos Extra, in boxes of 12 and 24 and in packs of 5, says habanos.com.","vitolas":["Coloniales"],"wrapper":"Vuelta Abajo"},{"name":"Robustos Extra","color":"#722F37","force":"Medium","story":"A vitola of ring gauge 50 x 155 mm, presented in 2003, in boxes of 12 and 24 and in packs of 3, says habanos.com, whose brand page also dates the Robustos T to 2009 (without giving their dimensions; Wikipedia lists them at 4 7/8 inches x 50). The Robustos Extra, discontinued earlier according to the trade press, returned to regular production in February 2024 for the brand''s 55th anniversary (6 1/8 inches x cepo 50, boxes of 12 and of 3, new presentation). The current status of the Robustos T is not established by any page read.","vitolas":["Robustos Extra","Robustos T"],"wrapper":"Vuelta Abajo"},{"name":"Vigía, Topes, Esmeralda et Media Luna","color":"#6B8E23","force":"Medium","story":"Vigía: vitola de galera Torres, ring gauge 54 (21.43 mm) x 110 mm, presented in April 2014. Topes: ring gauge 56 (22.23 mm) x 125 mm, Edición Limitada 2016 then regular range in 2019. Esmeralda (ring gauge 53 x 145 mm) and Media Luna (ring gauge 50 x 115 mm): 2019. All according to habanos.com, which gives the brand as medium in strength.","vitolas":[],"wrapper":"Vuelta Abajo"}]',
  `gamme_es` = '[{"name":"Fundadores","color":"#8B6914","force":"Medium","story":"Única vitola de la marca en sus comienzos, dice habanos.com, que la da con cepo 40 y 192 mm de largo (comunicado del 7 de octubre de 2003); sigue entonces en la gama, en cofres barnizados de 12 y 24 y en paquetes de 5. La prensa del oficio la anota en 7 1/2 pulgadas x 40 (2019). Habanos clasifica la marca en fuerza media.","vitolas":["Fundadores"],"wrapper":"Vuelta Abajo"},{"name":"Reyes","color":"#A0522D","force":"Medium","story":"Vitola de cepo 40 x 110 mm, presentada en Londres el 10 de noviembre de 2003 junto con los Coloniales y los Robustos Extra, en cofres de 12 y 24 y en paquetes de 5, dice habanos.com.","vitolas":["Reyes"],"wrapper":"Vuelta Abajo"},{"name":"Coloniales","color":"#8B4513","force":"Medium","story":"Vitola de cepo 44 x 132 mm, presentada en 2003 al mismo tiempo que los Reyes y los Robustos Extra, en cofres de 12 y 24 y en paquetes de 5, dice habanos.com.","vitolas":["Coloniales"],"wrapper":"Vuelta Abajo"},{"name":"Robustos Extra","color":"#722F37","force":"Medium","story":"Vitola de cepo 50 x 155 mm, presentada en 2003, en cofres de 12 y 24 y en paquetes de 3, dice habanos.com, cuya página de marca fecha también en 2009 los Robustos T (sin dar sus medidas; Wikipedia los lista en 4 7/8 pulgadas x 50). Los Robustos Extra, retirados antes según la prensa del oficio, volvieron a la producción regular en febrero de 2024 por los 55 años de la marca (6 1/8 pulgadas x cepo 50, cajas de 12 y de 3, nueva presentación). El estado actual de los Robustos T no lo establece ninguna página leída.","vitolas":["Robustos Extra","Robustos T"],"wrapper":"Vuelta Abajo"},{"name":"Vigía, Topes, Esmeralda et Media Luna","color":"#6B8E23","force":"Medium","story":"Vigía: vitola de galera Torres, cepo 54 (21,43 mm) x 110 mm, presentada en abril de 2014. Topes: cepo 56 (22,23 mm) x 125 mm, Edición Limitada 2016 y luego gama regular en 2019. Esmeralda (cepo 53 x 145 mm) y Media Luna (cepo 50 x 115 mm): 2019. Todas según habanos.com, que da la marca en fuerza media.","vitolas":[],"wrapper":"Vuelta Abajo"}]',
  `gamme_de` = '[{"name":"Fundadores","color":"#8B6914","force":"Medium","story":"Einzige Vitola der Marke zu Beginn, laut habanos.com, wo sie mit Ringmaß 40 und 192 mm Länge angegeben wird (Pressemitteilung vom 7. Oktober 2003); sie bleibt danach im Programm, in klarlackierten Kisten zu 12 und 24 und in Päckchen zu 5. Die Fachpresse führt sie mit 7 1/2 Zoll x 40 (2019). Habanos stuft die Marke in mittlerer Stärke ein.","vitolas":["Fundadores"],"wrapper":"Vuelta Abajo"},{"name":"Reyes","color":"#A0522D","force":"Medium","story":"Vitola mit Ringmaß 40 x 110 mm, am 10. November 2003 in London zusammen mit den Coloniales und den Robustos Extra vorgestellt, in Kisten zu 12 und 24 und in Päckchen zu 5, sagt habanos.com.","vitolas":["Reyes"],"wrapper":"Vuelta Abajo"},{"name":"Coloniales","color":"#8B4513","force":"Medium","story":"Vitola mit Ringmaß 44 x 132 mm, 2003 zugleich mit den Reyes und den Robustos Extra vorgestellt, in Kisten zu 12 und 24 und in Päckchen zu 5, sagt habanos.com.","vitolas":["Coloniales"],"wrapper":"Vuelta Abajo"},{"name":"Robustos Extra","color":"#722F37","force":"Medium","story":"Vitola mit Ringmaß 50 x 155 mm, 2003 vorgestellt, in Kisten zu 12 und 24 und in Päckchen zu 3, sagt habanos.com, dessen Markenseite außerdem die Robustos T auf 2009 datiert (ohne ihre Maße anzugeben; Wikipedia führt sie mit 4 7/8 Zoll x 50 auf). Die Robustos Extra, zuvor laut Fachpresse eingestellt, kehrten im Februar 2024 zum 55-jährigen Bestehen der Marke in die reguläre Produktion zurück (6 1/8 Zoll x cepo 50, Kisten zu 12 und zu 3, neue Aufmachung). Der aktuelle Status der Robustos T ist durch keine gelesene Seite belegt.","vitolas":["Robustos Extra","Robustos T"],"wrapper":"Vuelta Abajo"},{"name":"Vigía, Topes, Esmeralda et Media Luna","color":"#6B8E23","force":"Medium","story":"Vigía: Vitola de galera Torres, Ringmaß 54 (21,43 mm) x 110 mm, im April 2014 vorgestellt. Topes: Ringmaß 56 (22,23 mm) x 125 mm, Edición Limitada 2016, dann 2019 reguläre Reihe. Esmeralda (Ringmaß 53 x 145 mm) und Media Luna (Ringmaß 50 x 115 mm): 2019. Alle laut habanos.com, das die Marke in mittlerer Stärke angibt.","vitolas":[],"wrapper":"Vuelta Abajo"}]',
  `gamme_zh` = '[{"name":"Fundadores","color":"#8B6914","force":"Medium","story":"据 habanos.com，这是该品牌起步时仅有的规格，该网站给出的是环径 40、长 192 毫米（2003年10月7日新闻稿）；此后它仍留在产品线中，有上了清漆的12支装和24支装盒，以及5支装小包。行业媒体记其为 7 1/2 英寸 x 40（2019年）。Habanos 把这个品牌归为中等强度。","vitolas":["Fundadores"],"wrapper":"Vuelta Abajo"},{"name":"Reyes","color":"#A0522D","force":"Medium","story":"据 habanos.com，这是一个环径 40 x 110 毫米的规格，于2003年11月10日在伦敦与 Coloniales 和 Robustos Extra 一同推出，有12支装和24支装盒，以及5支装小包。","vitolas":["Reyes"],"wrapper":"Vuelta Abajo"},{"name":"Coloniales","color":"#8B4513","force":"Medium","story":"据 habanos.com，这是一个环径 44 x 132 毫米的规格，于2003年与 Reyes 和 Robustos Extra 同时推出，有12支装和24支装盒，以及5支装小包。","vitolas":["Coloniales"],"wrapper":"Vuelta Abajo"},{"name":"Robustos Extra","color":"#722F37","force":"Medium","story":"据 habanos.com，这是一个环径 50 x 155 毫米的规格，于2003年推出，有12支装和24支装盒，以及3支装小包；该网站的品牌页面还把 Robustos T 定在2009年（未给出尺寸；维基百科列为 4 7/8 英寸 x 50）。Robustos Extra 此前据行业媒体已停产，于2024年2月为纪念品牌55周年恢复常规生产（6 1/8 英寸 x cepo 50，12支装和3支装盒，新包装）。Robustos T 的当前状况，所读页面均未确立。","vitolas":["Robustos Extra","Robustos T"],"wrapper":"Vuelta Abajo"},{"name":"Vigía, Topes, Esmeralda et Media Luna","color":"#6B8E23","force":"Medium","story":"Vigía：galera 名称为 Torres 的规格，环径 54（21.43 毫米）x 110 毫米，2014年4月推出。Topes：环径 56（22.23 毫米）x 125 毫米，2016年为 Edición Limitada，2019年转入常规系列。Esmeralda（环径 53 x 145 毫米）和 Media Luna（环径 50 x 115 毫米）：2019年。以上均据 habanos.com，该网站把这个品牌归为中等强度。","vitolas":[],"wrapper":"Vuelta Abajo"}]',
  `gamme_ar` = '[{"name":"Fundadores","color":"#8B6914","force":"Medium","story":"القياس الوحيد للعلامة في بداياتها، بحسب موقع habanos.com الذي يعطيه بقياس حلقي 40 وطول 192 مم (بيان 7 أكتوبر 2003)؛ ويبقى بعدها في المجموعة، في علب مطلية بالورنيش من 12 و24 وفي رزم من 5. وتسجّله الصحافة المتخصّصة بقياس 7 1/2 بوصة x 40 (2019). وتصنّف Habanos العلامة بقوة متوسطة.","vitolas":["Fundadores"],"wrapper":"Vuelta Abajo"},{"name":"Reyes","color":"#A0522D","force":"Medium","story":"قياس حلقي 40 x 110 مم، قُدّم في لندن في 10 نوفمبر 2003 مع Coloniales وRobustos Extra، في علب من 12 و24 وفي رزم من 5، بحسب موقع habanos.com.","vitolas":["Reyes"],"wrapper":"Vuelta Abajo"},{"name":"Coloniales","color":"#8B4513","force":"Medium","story":"قياس حلقي 44 x 132 مم، قُدّم عام 2003 في الوقت نفسه مع Reyes وRobustos Extra، في علب من 12 و24 وفي رزم من 5، بحسب موقع habanos.com.","vitolas":["Coloniales"],"wrapper":"Vuelta Abajo"},{"name":"Robustos Extra","color":"#722F37","force":"Medium","story":"قياس حلقي 50 x 155 مم، قُدّم عام 2003، في علب من 12 و24 وفي رزم من 3، بحسب موقع habanos.com الذي تؤرّخ صفحة العلامة فيه أيضًا Robustos T بعام 2009 (من دون ذكر مقاساتها؛ وتدرجها ويكيبيديا بـ 4 7/8 بوصة x 50). وقد عاد Robustos Extra، الذي توقّف قبل ذلك بحسب الصحافة المتخصّصة، إلى الإنتاج المنتظم في فبراير 2024 بمناسبة مرور 55 عامًا على العلامة (6 1/8 بوصة x cepo 50، علب من 12 ومن 3، تقديم جديد). أما الوضع الحالي لـRobustos T فلا تثبته أي صفحة مقروءة.","vitolas":["Robustos Extra","Robustos T"],"wrapper":"Vuelta Abajo"},{"name":"Vigía, Topes, Esmeralda et Media Luna","color":"#6B8E23","force":"Medium","story":"Vigía: vitola de galera باسم Torres، قياس حلقي 54 (21.43 مم) x 110 مم، قُدّم في أبريل 2014. Topes: قياس حلقي 56 (22.23 مم) x 125 مم، Edición Limitada 2016 ثم المجموعة العادية عام 2019. Esmeralda (قياس حلقي 53 x 145 مم) وMedia Luna (قياس حلقي 50 x 115 مم): 2019. وكلها بحسب موقع habanos.com الذي يعطي العلامة قوةً متوسطة.","vitolas":[],"wrapper":"Vuelta Abajo"}]',
  `source` = IF(LOCATE(CAST('habanos.com « Trinidad La Trova, Habanos, S.A. world present' AS BINARY), CAST(`source` AS BINARY)) > 0, `source`, CONCAT(`source`, ' ; ', 'habanos.com « Trinidad La Trova, Habanos, S.A. world presentation in Asia Pacific » (14 novembre 2017 : fabriquée aujourd''hui à la fabrique Francisco Donatién, Pinar del Río ; 52 x 166 mm) ; cigaraficionado.com « New Cuban Trinidad to Debut in Asia-Pacific Region » (15 novembre 2017 : Francisco Donatién, aussi dite fabrique Vegueros) ; blindmanspuff.com « Cigar News: TRINIDAD LA TROVA, New Exclusive for La Casa Del Habano » (20 novembre 2017) ; simplycigars.co.uk « Trinidad Cigars » (détaillant, sans date : production transférée à Pinar del Río en 2004) ; en.wikipedia.org « Trinidad (cigar) » (sans date : liste des vitolas dont Robusto Extra 6 1/8 x 50 et Robusto T 4 7/8 x 50) ; cigaraficionado.com « New Cuban Cigars Announced at 24th Habanos Festival » (26 février 2024 : Robusto Extra de retour en production régulière) ; prensa-latina.cu « Novedades de habanos en primeros planos desde Cuba » (27 février 2024 : Robustos Extra élargissent le portefeuille standard)')),
  `updated_at` = NOW()
 WHERE `name` = 'Trinidad';

