UPDATE `producer_countries` SET
  `brands` = '[{"desc":"Née en 1966, fabrique El Laguito ; l''une des six marques globales de Habanos","name":"Cohiba","iconic":true},{"desc":"Née en 1935 à la fabrique H. Upmann ; l''une des six marques globales","name":"Montecristo","iconic":true},{"desc":"Fabrique créée en 1845 par Jaime Partagás, dit Habanos ; fabrique mère Partagás ; marque globale","name":"Partagás","iconic":true},{"desc":"Nom créé en 1875 selon Habanos ; marque globale ; Churchills, vitola la plus connue de la marque, dit Habanos","name":"Romeo y Julieta","iconic":true},{"desc":"Marque de 1844 selon Habanos, fondée par le banquier allemand Herman Upmann ; marque globale","name":"H. Upmann","iconic":false},{"desc":"Créée en 1902 selon Habanos ; nom de Simón Bolívar ; fabrique mère Partagás ; marque de valeur","name":"Bolivar","iconic":false},{"desc":"Créée en 1969 pour les cadeaux diplomatiques, commercialisée en 1998 ; marque de valeur","name":"Trinidad","iconic":false},{"desc":"Enregistrée en 1840 selon Habanos, pour le marché anglais ; fabrique La Corona, avec Hoyo de Monterrey","name":"Punch","iconic":false},{"desc":"Marque enregistrée en 1865 par José Gener ; plantation de San Juan y Martínez ; marque globale","name":"Hoyo de Monterrey","iconic":true},{"desc":"Créée en 1997 en hommage à Alejandro Robaina, planteur de San Luis ; fabrique non nommée par Habanos","name":"Vegas Robaina","iconic":false},{"desc":"Née à Cienfuegos, tripe courte roulée main, tabac de Vuelta Abajo ; marque de volume","name":"Quintero","iconic":false},{"desc":"1837 selon Habanos (1845 selon Wikipédia) ; fabrique mère Partagás selon la presse ; marque de valeur","name":"Ramón Allones","iconic":true},{"desc":"1882 selon Habanos, 1848 selon Wikipédia ; fabrique mère non nommée par Habanos","name":"El Rey del Mundo","iconic":false},{"desc":"Fondée en 1885 ; série Medaille d''Or ; tripe longue ; fabrique Partagás selon la presse du métier","name":"La Gloria Cubana","iconic":false},{"desc":"Années 1870 selon Habanos (1876 selon Wikipédia) ; Selección No. 1, No. 2 et Selección Especial","name":"Juan López","iconic":false},{"desc":"Fondée en 1834 ; tripe longue ou courte selon les vitoles ; fabrique La Corona selon la presse du métier","name":"Por Larrañaga","iconic":false},{"desc":"Années 1930 selon Habanos ; avis de dégustation sous le couvercle des boîtes ; fabrique non nommée","name":"Rafael González","iconic":false},{"desc":"Premier enregistrement en 1848, dit Habanos ; trois havanes au catalogue de Habanos","name":"Sancho Panza","iconic":false},{"desc":"Avant la Seconde Guerre mondiale selon Habanos (1940 selon Wikipédia) ; nom de San Luis, hypothèse de Habanos","name":"Saint Luis Rey","iconic":false},{"desc":"Années 1960 selon Habanos (1966 selon la presse) ; fabrique H. Upmann selon la presse (2011)","name":"Diplomáticos","iconic":false},{"desc":"Fondée dans les années 1890 ; présentée sous papier de soie ; tripe longue et courte","name":"Fonseca","iconic":false},{"desc":"Style de la fin du XIXe siècle relancé en 1996, dit Habanos ; fabrique mère La Corona selon la presse","name":"Cuaba","iconic":false},{"desc":"Lancée en 1999 ; vitoles aux noms de quatre forteresses de La Havane ; réseau Casas del Habano","name":"San Cristóbal de La Habana","iconic":false},{"desc":"Lancée en 1996 (1997 selon d''autres lectures) à Pinar del Río ; fabrique Francisco Donatien ; marque de volume","name":"Vegueros","iconic":false},{"desc":"Créée en 1973 ; marque de valeur en octobre 2026 ; fabrique Partagás selon la presse du métier","name":"Quai d''Orsay","iconic":false},{"desc":"Famille venue des Asturies dans les années 1880 ; tripe courte roulée main, tabac de Remedios ; marque de volume","name":"José L. Piedra","iconic":false},{"desc":"1884 selon Habanos ; tripe courte roulée main ; fabrique La Corona selon la presse du métier","name":"La Flor de Cano","iconic":false}]',
  `updated_at` = NOW()
 WHERE `id` = 'cuba';

