  `factories` = '[{"name":"El Laguito","city":"La Havane","founded":"1966","marques":["Cohiba"]},{"name":"Francisco Donatien","city":"Pinar del Río","founded":"1961","marques":["Trinidad","Vegueros"]},{"name":"Partagás","city":"La Havane","founded":"2011-2012 (site actuel, San Carlos 806)","marques":["Partagás","Bolivar","Ramón Allones","La Gloria Cubana","Quai d''Orsay"]},{"name":"H. Upmann (José Martí)","city":"La Havane","founded":"1960 (site actuel depuis 2011)","marques":["H. Upmann","Montecristo","Diplomáticos"]},{"name":"Romeo y Julieta (fabrique non nommée par Habanos)","city":"La Havane","founded":"Carlos Baliño, Marianao, dite en 2024 la nouvelle fabrique (presse)","marques":["Romeo y Julieta"]},{"name":"La Corona (Miguel Fernández Roig)","city":"La Havane","founded":"Cerro, fabrique de cigares depuis 2000","marques":["Punch","Hoyo de Monterrey","Cuaba","Por Larrañaga","La Flor de Cano","San Cristóbal de La Habana"]},{"name":"Fabrique mère non nommée par Habanos","city":"Cuba","founded":"—","marques":["Fonseca","Juan López","Rafael González","Sancho Panza","Vegas Robaina","Quintero","José L. Piedra","El Rey del Mundo","Saint Luis Rey"]}]'
