-- ── Les sceaux des champs réécrits, calculés depuis les colonnes françaises ──
INSERT INTO `translation_status` (`entite`, `entite_id`, `champ`, `lang`, `source_hash`, `statut`, `relecteur`, `maj`)
SELECT 'brands', b.`name`, c.champ, l.lang,
       SHA1(CASE c.champ WHEN 'history' THEN b.`history` WHEN 'celebrities' THEN b.`celebrities` WHEN 'pairings' THEN b.`pairings` ELSE b.`gamme` END), 'machine', NULL, NOW()
  FROM `brands` b
  JOIN (SELECT 'Por Larrañaga' hote, 'celebrities' champ
        UNION ALL SELECT 'Por Larrañaga' hote, 'gamme' champ
        UNION ALL SELECT 'Por Larrañaga' hote, 'history' champ
        UNION ALL SELECT 'Por Larrañaga' hote, 'pairings' champ
        UNION ALL SELECT 'La Gloria Cubana' hote, 'celebrities' champ
        UNION ALL SELECT 'La Gloria Cubana' hote, 'gamme' champ
        UNION ALL SELECT 'La Gloria Cubana' hote, 'history' champ
        UNION ALL SELECT 'La Gloria Cubana' hote, 'pairings' champ
        UNION ALL SELECT 'Juan López' hote, 'gamme' champ
        UNION ALL SELECT 'Juan López' hote, 'history' champ
        UNION ALL SELECT 'Juan López' hote, 'pairings' champ
        UNION ALL SELECT 'Rafael González' hote, 'celebrities' champ
        UNION ALL SELECT 'Rafael González' hote, 'gamme' champ
        UNION ALL SELECT 'Rafael González' hote, 'history' champ
        UNION ALL SELECT 'Rafael González' hote, 'pairings' champ
        UNION ALL SELECT 'Sancho Panza' hote, 'celebrities' champ
        UNION ALL SELECT 'Sancho Panza' hote, 'gamme' champ
        UNION ALL SELECT 'Sancho Panza' hote, 'history' champ
        UNION ALL SELECT 'Sancho Panza' hote, 'pairings' champ
        UNION ALL SELECT 'Saint Luis Rey' hote, 'gamme' champ
        UNION ALL SELECT 'Saint Luis Rey' hote, 'history' champ
        UNION ALL SELECT 'Saint Luis Rey' hote, 'pairings' champ
        UNION ALL SELECT 'Quai d''Orsay' hote, 'celebrities' champ
        UNION ALL SELECT 'Quai d''Orsay' hote, 'gamme' champ
        UNION ALL SELECT 'Quai d''Orsay' hote, 'history' champ
        UNION ALL SELECT 'Quai d''Orsay' hote, 'pairings' champ
        UNION ALL SELECT 'San Cristóbal de La Habana' hote, 'celebrities' champ
        UNION ALL SELECT 'San Cristóbal de La Habana' hote, 'gamme' champ
        UNION ALL SELECT 'San Cristóbal de La Habana' hote, 'history' champ
        UNION ALL SELECT 'San Cristóbal de La Habana' hote, 'pairings' champ
        UNION ALL SELECT 'La Flor de Cano' hote, 'gamme' champ
        UNION ALL SELECT 'La Flor de Cano' hote, 'history' champ
        UNION ALL SELECT 'La Flor de Cano' hote, 'pairings' champ
        UNION ALL SELECT 'Fonseca' hote, 'celebrities' champ
        UNION ALL SELECT 'Fonseca' hote, 'gamme' champ
        UNION ALL SELECT 'Fonseca' hote, 'history' champ
        UNION ALL SELECT 'Fonseca' hote, 'pairings' champ
        UNION ALL SELECT 'H. Upmann' hote, 'gamme' champ
        UNION ALL SELECT 'Montecristo' hote, 'gamme' champ
        UNION ALL SELECT 'Trinidad' hote, 'gamme' champ
        UNION ALL SELECT 'Trinidad' hote, 'history' champ) c
  JOIN (SELECT 'en' lang UNION ALL SELECT 'es' UNION ALL SELECT 'de' UNION ALL SELECT 'zh' UNION ALL SELECT 'ar') l
 WHERE c.hote = b.`name`
    ON DUPLICATE KEY UPDATE `source_hash` = VALUES(`source_hash`), `statut` = 'machine', `relecteur` = NULL, `maj` = NOW();

