UNION ALL SELECT 'Juan López', 'zh', 'histoire 3 (nouveau texte)', (LOCATE(CAST('据行业媒体，Selección No. 2 是一款罗布图，4 7/8 英寸，cepo 50（124 毫米）；habanos.com 把它与 Selección No. 1 一并列为 vitolario 的核心。Selección No. 1 长 5 5/8 英寸，cepo 46（143 毫米）：行业媒体在其资料卡中把它归入 Toro，而在品鉴笔记中称它为 corona gorda。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Juan López'
UNION ALL SELECT 'Juan López', 'zh', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Seleccion No.2 这款罗布图是它最知名的表达，也大概是整个哈瓦那目录中付出与所得之比最好的一支。爱好者常说，这是你递给「自以为什么都抽过」的人的那支哈瓦那。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Juan López'
UNION ALL SELECT 'Juan López', 'ar', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Selección No. 2 هو روبوستو بطول 4 7/8 بوصة على cepo 50 (124 مم) بحسب الصحافة المتخصّصة؛ وتذكره habanos.com مع Selección No. 1 في صميم vitolario. ويبلغ طول Selección No. 1 ما قدره 5 5/8 بوصة على cepo 46 (143 مم): وتدرجه الصحافة المتخصّصة في بطاقتها تحت Toro وتسمّيه corona gorda في ملاحظة التذوق.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Juan López'
UNION ALL SELECT 'Juan López', 'ar', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('أمّا «سيليكسيون رقم 2»، وهو روبوستو، فهو تعبيرها الأشهر، وربما أفضل نسبة بين ما تدفعه وما تناله في كتالوغ هافانا كلّه. ويذكره الهواة بانتظام بوصفه الهافانا الذي تهديه لمن يظنّ أنه دخّن كل شيء.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Juan López'
UNION ALL SELECT 'Juan López', 'fr', 'histoire 4 (nouveau texte)', (LOCATE(CAST('La Selección Especial, 52 x 170 mm, en coffret de 25, a été annoncée au XXII Festival del Habano (26 février 2020, Cigar Coop) puis présentée en première mondiale au Benelux le 4 décembre 2021 (habanos.com) ; elle est vendue dans les Casas del Habano.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Juan López'
UNION ALL SELECT 'Juan López', 'fr', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('Les séries régionales ont ici aussi joué un rôle : quelques éditions locales ont fait connaître Juan López à des marchés qui l''ignoraient, et ont contribué à sa réputation de secret partagé.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Juan López'
UNION ALL SELECT 'Juan López', 'en', 'histoire 4 (nouveau texte)', (LOCATE(CAST('The Selección Especial, 52 x 170 mm, in a box of 25, was announced at the XXII Festival del Habano (26 February 2020, Cigar Coop) and then presented as a world première in the Benelux on 4 December 2021 (habanos.com); it is sold in the Casas del Habano.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Juan López'
UNION ALL SELECT 'Juan López', 'en', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('The regional series have played a part here too: a few local editions made Juan López known to markets that had ignored it, and helped build its reputation as a shared secret.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Juan López'
UNION ALL SELECT 'Juan López', 'es', 'histoire 4 (nouveau texte)', (LOCATE(CAST('La Selección Especial, 52 x 170 mm, en estuche de 25, se anunció en el XXII Festival del Habano (26 de febrero de 2020, Cigar Coop) y se presentó en estreno mundial en el Benelux el 4 de diciembre de 2021 (habanos.com); se vende en las Casas del Habano.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Juan López'
UNION ALL SELECT 'Juan López', 'es', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('Las series regionales también han jugado aquí un papel: algunas ediciones locales dieron a conocer Juan López a mercados que lo ignoraban, y contribuyeron a su fama de secreto compartido.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Juan López'
UNION ALL SELECT 'Juan López', 'de', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Die Selección Especial, 52 x 170 mm, in der Kassette zu 25 Stück, wurde auf dem XXII Festival del Habano (26. Februar 2020, Cigar Coop) angekündigt und dann am 4. Dezember 2021 als Weltpremiere in den Benelux-Ländern vorgestellt (habanos.com); sie wird in den Casas del Habano verkauft.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Juan López'
UNION ALL SELECT 'Juan López', 'de', 'histoire 4 (ancien texte parti)', (LOCATE(CAST('Auch hier haben die Regionalserien eine Rolle gespielt: Einige lokale Editionen machten Juan López Märkten bekannt, die sie nicht kannten, und trugen zu ihrem Ruf als geteiltes Geheimnis bei.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Juan López'
UNION ALL SELECT 'Juan López', 'zh', 'histoire 4 (nouveau texte)', (LOCATE(CAST('Selección Especial，52 x 170 毫米，25支装盒，在 XXII Festival del Habano（2020年2月26日，Cigar Coop）上宣布，随后于2021年12月4日在比荷卢地区作全球首发（habanos.com）；在 Casas del Habano 有售。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Juan López'
