UNION ALL SELECT 'Rafael González', 'fr', 'factory', (CAST(`factory` AS BINARY) = CAST('Fabrique mère non nommée par Habanos ni par la presse du métier consultée (2011, 2023) ; roulée à Cuba sous le régime des fabriques mères' AS BINARY)) FROM `brands` WHERE `name` = 'Rafael González'
UNION ALL SELECT 'Rafael González', 'fr', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Rafael González est, dit habanos.com, une marque créée dans les années 1930, dont les boîtes portent une inscription en anglais : fumer les cigares dans le mois suivant la date d''expédition de La Havane, sinon les laisser mûrir soigneusement environ un an. La presse du métier écrit en 2023 que les anciennes boîtes blanches de la marque portaient du texte sur le couvercle. Habanos écrit aussi que sa vitola de fabrique s''appelle Cervantes et fut d''abord appelée Lonsdale, d''après Lord Lonsdale.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Rafael González'
UNION ALL SELECT 'Rafael González', 'fr', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Rafael González est la seule marque cubaine à porter, imprimée à l''intérieur du couvercle de ses boîtes, une recommandation de dégustation : fumer ces cigares dans l''année qui suit leur fabrication, ou les laisser vieillir plus d''un an. Entre les deux, dit l''avis, ils traversent une période creuse. Le texte, rédigé en anglais et attribué à un marquis britannique, date de la création de la marque en 1928, quand elle fut lancée à destination du marché anglais.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Rafael González'
UNION ALL SELECT 'Rafael González', 'en', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Rafael González is, says habanos.com, a brand created in the 1930s, whose boxes bear an inscription in English: smoke the cigars within the month following their date of dispatch from Havana, otherwise let them mature carefully for about a year. In 2023 the trade press writes that the brand''s old white boxes carried text on the lid. Habanos also writes that its factory vitola is called Cervantes and was first called Lonsdale, after Lord Lonsdale.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Rafael González'
UNION ALL SELECT 'Rafael González', 'en', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Rafael González is the only Cuban brand to carry, printed inside the lid of its boxes, a smoking recommendation: smoke these cigars within the year of their making, or let them age more than a year. In between, the notice says, they pass through a hollow period. The text, written in English and attributed to a British marquess, dates from the creation of the brand in 1928, when it was launched for the English market.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Rafael González'
UNION ALL SELECT 'Rafael González', 'es', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Rafael González es, dice habanos.com, una marca creada en los años treinta, cuyas cajas llevan una inscripción en inglés: fumar los puros en el mes siguiente a la fecha de expedición desde La Habana; si no, dejarlos madurar con cuidado durante un año aproximadamente. La prensa del oficio escribe en 2023 que las antiguas cajas blancas de la marca llevaban texto en la tapa. Habanos escribe también que su vitola de galera se llama Cervantes y se llamó primero Lonsdale, por Lord Lonsdale.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Rafael González'
UNION ALL SELECT 'Rafael González', 'es', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Rafael González es la única marca cubana que lleva, impresa en el interior de la tapa de sus cajas, una recomendación de degustación: fumar estos cigarros en el año siguiente a su fabricación, o dejarlos envejecer más de un año. Entre ambos momentos, dice el aviso, atraviesan un período hueco. El texto, redactado en inglés y atribuido a un marqués británico, data de la creación de la marca en 1928, cuando se lanzó con destino al mercado inglés.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Rafael González'
UNION ALL SELECT 'Rafael González', 'de', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Rafael González ist, so habanos.com, eine in den 1930er Jahren geschaffene Marke, deren Kisten eine englische Inschrift tragen: die Zigarren innerhalb eines Monats nach dem Versanddatum aus Havanna zu rauchen, andernfalls sorgfältig etwa ein Jahr reifen zu lassen. Die Fachpresse schreibt 2023, dass die alten weißen Kisten der Marke Text auf dem Deckel trugen. Habanos schreibt außerdem, dass ihr Fabrikformat Cervantes heißt und zuerst Lonsdale genannt wurde, nach Lord Lonsdale.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Rafael González'
UNION ALL SELECT 'Rafael González', 'de', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Rafael González ist die einzige kubanische Marke, die im Inneren ihres Kistendeckels eine Genussempfehlung abgedruckt trägt: diese Zigarren innerhalb eines Jahres nach ihrer Herstellung zu rauchen oder sie länger als ein Jahr reifen zu lassen. Dazwischen, so der Hinweis, durchlaufen sie eine Senke. Der Text, auf Englisch verfasst und einem britischen Marquess zugeschrieben, stammt aus dem Gründungsjahr 1928, als die Marke für den englischen Markt aufgelegt wurde.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Rafael González'
UNION ALL SELECT 'Rafael González', 'zh', 'histoire 1 (nouveau texte)', (LOCATE(CAST('据 habanos.com，Rafael González 是一个创立于1930年代的品牌，其盒子上印有一段英文：雪茄应在从哈瓦那发货之日起一个月内抽完，否则就小心地让它陈化约一年。行业媒体2023年写道，该品牌旧时的白色盒子盒盖上印有文字。Habanos 还写道，其厂内规格名为 Cervantes，起初叫 Lonsdale，取自 Lord Lonsdale。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Rafael González'
UNION ALL SELECT 'Rafael González', 'zh', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('拉斐尔·冈萨雷斯是唯一在盒盖内侧印有品吸建议的古巴品牌：这些雪茄要么在制成后的一年内抽掉，要么陈化一年以上。那份说明称，两者之间它们会经历一段低谷期。这段以英文写就、据称出自一位英国侯爵之手的文字，可追溯至1928年品牌创立之时——它当时正是为英国市场而推出。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Rafael González'
UNION ALL SELECT 'Rafael González', 'ar', 'histoire 1 (nouveau texte)', (LOCATE(CAST('تقول habanos.com إن Rafael González علامة أُنشئت في ثلاثينيات القرن العشرين، وتحمل صناديقها نقشًا بالإنجليزية: تُدخَّن السيجارات في غضون شهر من تاريخ شحنها من هافانا، وإلا فتُترك لتنضج بعناية نحو سنة. وتكتب الصحافة المتخصّصة سنة 2023 أن صناديق العلامة البيضاء القديمة كانت تحمل نصًا على الغطاء. وتكتب Habanos أيضًا أن قياس مصنعها يُسمّى Cervantes وسُمّي في البدء Lonsdale، نسبةً إلى Lord Lonsdale.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Rafael González'
UNION ALL SELECT 'Rafael González', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('«رافائيل غونزاليس» العلامة الكوبية الوحيدة التي تحمل، مطبوعةً داخل غطاء صناديقها، توصيةَ تذوّق: أن تُدخَّن هذه السيجارات في غضون سنة من صنعها، أو أن تُترك لتتعتّق أكثر من سنة. وبين الأمرين، يقول التنبيه، تمرّ بفترة خاوية. والنصّ، المحرَّر بالإنكليزية والمنسوب إلى ماركيز بريطاني، يعود إلى تأسيس العلامة سنة 1928، حين أُطلقت للسوق الإنكليزية.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Rafael González'
UNION ALL SELECT 'Rafael González', 'fr', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Habanos la classe en force légère ; ses cigares sont roulés entièrement à la main, en tripe longue sauf une vitola en tripe courte, avec de la tripe et du liant de la Vuelta Abajo, dans la province de Pinar del Río. La presse du métier la décrit en 2023 comme une marque très petite, créée dans les années 1930, que bien des fumeurs remarquent peu.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Rafael González'
UNION ALL SELECT 'Rafael González', 'fr', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('L''avis dit quelque chose de vrai sur la marque : son assemblage, dans le registre doux à médium, se lit très tôt et très tard, mais s''efface au milieu. C''est une particularité que peu de maisons assument par écrit.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Rafael González'
UNION ALL SELECT 'Rafael González', 'en', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Habanos classes it as light in strength; its cigars are entirely hand-rolled, with long filler except for one vitola with short filler, using filler and binder from the Vuelta Abajo, in the province of Pinar del Río. In 2023 the trade press describes it as a very small brand, created in the 1930s, that many smokers barely notice.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Rafael González'
