UNION ALL SELECT 'Sancho Panza', 'fr', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Le choix du nom dit tout : non pas Don Quichotte, mais son écuyer — le personnage terre à terre, celui qui mange, dort et ne poursuit pas de moulins. La marque, fondée en 1848, a construit son profil sur cette promesse de bon sens : un cigare doux à médium, sans aspérité, fait pour être fumé plutôt que commenté.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Sancho Panza'
UNION ALL SELECT 'Sancho Panza', 'en', 'histoire 1 (nouveau texte)', (LOCATE(CAST('The choice of name says it all: not Don Quixote, but his squire — the down-to-earth character, the one who eats, sleeps and does not charge at windmills. The brand, whose first registration habanos.com dates to 1848, now presents itself at medium strength, entirely hand-rolled with long filler.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Sancho Panza'
UNION ALL SELECT 'Sancho Panza', 'en', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('The choice of name says it all: not Don Quixote, but his squire — the down-to-earth character, the one who eats, sleeps and does not charge at windmills. The brand, founded in 1848, built its profile on that promise of common sense: a mild-to-medium cigar, without rough edges, made to be smoked rather than commented upon.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Sancho Panza'
UNION ALL SELECT 'Sancho Panza', 'es', 'histoire 1 (nouveau texte)', (LOCATE(CAST('La elección del nombre lo dice todo: no Don Quijote, sino su escudero — el personaje con los pies en la tierra, el que come, duerme y no persigue molinos. La marca, cuyo primer registro habanos.com fecha en 1848, se presenta hoy con fuerza media, enteramente liada a mano con tripa larga.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Sancho Panza'
UNION ALL SELECT 'Sancho Panza', 'es', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('La elección del nombre lo dice todo: no Don Quijote, sino su escudero — el personaje con los pies en la tierra, el que come, duerme y no persigue molinos. La marca, fundada en 1848, construyó su perfil sobre esa promesa de sentido común: un cigarro suave a medio, sin asperezas, hecho para fumarse antes que para comentarse.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Sancho Panza'
UNION ALL SELECT 'Sancho Panza', 'de', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Die Wahl des Namens sagt alles: nicht Don Quijote, sondern sein Knappe — die bodenständige Figur, die isst, schläft und nicht gegen Windmühlen anreitet. Die Marke, deren erste Eintragung habanos.com auf 1848 datiert, präsentiert sich heute in mittlerer Stärke, vollständig von Hand gerollt, als Longfiller.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Sancho Panza'
UNION ALL SELECT 'Sancho Panza', 'de', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Die Wahl des Namens sagt alles: nicht Don Quijote, sondern sein Knappe — die bodenständige Figur, die isst, schläft und nicht gegen Windmühlen anreitet. Die 1848 gegründete Marke baute ihr Profil auf diesem Versprechen des gesunden Menschenverstands auf: eine milde bis mittlere Zigarre, ohne Kanten, gemacht zum Rauchen und nicht zum Kommentieren.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Sancho Panza'
UNION ALL SELECT 'Sancho Panza', 'zh', 'histoire 1 (nouveau texte)', (LOCATE(CAST('这个名字的选择说明了一切：不是堂吉诃德，而是他的侍从——那个脚踏实地、吃饭睡觉、不去冲击风车的人物。这个品牌，其首次注册 habanos.com 系于1848年，如今呈现为中等浓度，全部以长茄芯手工卷制。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Sancho Panza'
UNION ALL SELECT 'Sancho Panza', 'zh', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('这个名字的选择说明了一切：不是堂吉诃德，而是他的侍从——那个脚踏实地、吃饭睡觉、不去冲击风车的人物。这个1848年创立的品牌，正是把自己的风格建立在这份常识的承诺之上：一支柔至中度、没有棱角的雪茄，是用来抽的，而不是用来评论的。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Sancho Panza'
UNION ALL SELECT 'Sancho Panza', 'ar', 'histoire 1 (nouveau texte)', (LOCATE(CAST('اختيار الاسم يقول كل شيء: لا دون كيخوته، بل حامل سلاحه — الشخصية الواقعية، تلك التي تأكل وتنام ولا تطارد طواحين الهواء. والعلامة، التي تؤرّخ habanos.com أول تسجيل لها بسنة 1848، تُقدَّم اليوم بقوة متوسطة، ملفوفة كلها يدوياً بحشوة طويلة.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Sancho Panza'
UNION ALL SELECT 'Sancho Panza', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('اختيار الاسم يقول كل شيء: لا دون كيخوته، بل حامل سلاحه — الشخصية الواقعية، تلك التي تأكل وتنام ولا تطارد طواحين الهواء. وقد بنت العلامة، المؤسَّسة سنة 1848، طابعها على وعد المنطق السليم هذا: سيجار لطيف إلى متوسط، بلا خشونة، صُنع ليُدخَّن لا ليُعلَّق عليه.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Sancho Panza'
UNION ALL SELECT 'Sancho Panza', 'fr', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Selon Wikipédia, Emilio Ohmsted enregistre le nom en 1848, pour une fabrique de la rue Angeles, à La Havane ; Ramón Allones acquiert la marque dans les années 1880 et la Rey del Mundo Cigar Co. l''achète en 1940, avant la nationalisation du 15 septembre 1960. Sur le goût, les pages divergent : un détaillant britannique décrit le Belicosos comme médium à doux, boisé, avec des touches de caramel et de noisette ; la presse du métier (2025) le dit médium à corsé, puissant, très proche du dessert.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Sancho Panza'
UNION ALL SELECT 'Sancho Panza', 'fr', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Sancho Panza a longtemps été très populaire en Espagne, son premier marché, et a bâti là une clientèle fidèle qui n''a jamais réclamé de changement. Le profil est resté celui d''origine : bois clair, herbe fraîche, une douceur beurrée, une force que la plupart des fumeurs qualifient de reposante.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Sancho Panza'
UNION ALL SELECT 'Sancho Panza', 'en', 'histoire 2 (nouveau texte)', (LOCATE(CAST('According to Wikipedia, Emilio Ohmsted registered the name in 1848, for a factory on Angeles Street in Havana; Ramón Allones acquired the brand in the 1880s and the Rey del Mundo Cigar Co. bought it in 1940, before the nationalisation of 15 September 1960. On flavour, the pages differ: a British retailer describes the Belicosos as medium to mild, woody, with touches of caramel and hazelnut; the trade press (2025) calls it medium to full, powerful, very close to dessert.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Sancho Panza'
UNION ALL SELECT 'Sancho Panza', 'en', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Sancho Panza was long very popular in Spain, its first market, and built there a loyal clientele that never asked for change. The profile has stayed the original one: pale wood, fresh grass, a buttery softness, a strength most smokers describe as restful.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Sancho Panza'
UNION ALL SELECT 'Sancho Panza', 'es', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Según Wikipedia, Emilio Ohmsted registra el nombre en 1848, para una fábrica de la calle Angeles, en La Habana; Ramón Allones adquiere la marca en la década de 1880 y la Rey del Mundo Cigar Co. la compra en 1940, antes de la nacionalización del 15 de septiembre de 1960. Sobre el sabor, las páginas divergen: un minorista británico describe el Belicosos como medio a suave, amaderado, con toques de caramelo y avellana; la prensa del oficio (2025) lo dice medio a fuerte, potente, muy próximo al postre.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Sancho Panza'
UNION ALL SELECT 'Sancho Panza', 'es', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Sancho Panza fue durante mucho tiempo muy popular en España, su primer mercado, y construyó allí una clientela fiel que nunca reclamó cambios. El perfil ha seguido siendo el de origen: madera clara, hierba fresca, una dulzura mantecosa, una fuerza que la mayoría de los fumadores califica de reposada.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Sancho Panza'
UNION ALL SELECT 'Sancho Panza', 'de', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Laut Wikipedia registriert Emilio Ohmsted den Namen 1848 für eine Fabrik in der Calle Angeles in Havanna; Ramón Allones erwirbt die Marke in den 1880er Jahren, und die Rey del Mundo Cigar Co. kauft sie 1940, vor der Verstaatlichung am 15. September 1960. Beim Geschmack gehen die Seiten auseinander: Ein britischer Händler beschreibt die Belicosos als mittelkräftig bis mild, holzig, mit Anklängen von Karamell und Haselnuss; die Fachpresse (2025) nennt sie mittelkräftig bis kräftig, stark, dem Dessert sehr nah.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Sancho Panza'
UNION ALL SELECT 'Sancho Panza', 'de', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Sancho Panza war lange sehr beliebt in Spanien, seinem ersten Markt, und baute dort eine treue Kundschaft auf, die nie nach Veränderung verlangte. Das Profil ist das ursprüngliche geblieben: helles Holz, frisches Gras, eine buttrige Weichheit, eine Kraft, die die meisten Raucher als erholsam beschreiben.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Sancho Panza'
UNION ALL SELECT 'Sancho Panza', 'zh', 'histoire 2 (nouveau texte)', (LOCATE(CAST('据维基百科，Emilio Ohmsted 于1848年为哈瓦那 Angeles 街的一家工厂注册了这个名字；Ramón Allones 在1880年代购得该品牌，Rey del Mundo Cigar Co. 于1940年将其买下，随后在1960年9月15日被国有化。关于口味，各页面说法不一：一家英国零售商把 Belicosos 描述为中等至柔和，带木质气息，并有焦糖和榛子的味道；行业媒体（2025）称其为中等至浓郁，劲道足，非常接近甜点。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Sancho Panza'
UNION ALL SELECT 'Sancho Panza', 'zh', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('桑丘·潘沙长期在其第一市场西班牙极受欢迎，并在那里建立起一批从不要求改变的忠实客群。风格一直是最初的那一种：浅色木质、青草、一种黄油般的柔和，以及大多数烟客形容为「令人安宁」的力度。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Sancho Panza'
