UNION ALL SELECT 'Saint Luis Rey', 'fr', 'histoire 2 (nouveau texte)', (LOCATE(CAST('La maison la dit corsée, appréciée des fumeurs qui recherchent des saveurs intenses, et souvent employée pour les éditions régionales. Les cigares sont roulés avec des feuilles de la zone de Vuelta Abajo, à Pinar del Río, pour la cape, la tripe et le liage.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Saint Luis Rey'
