UNION ALL SELECT 'Quai d''Orsay', 'en', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('The result is one of the palest blends in the Cuban portfolio — a blond wrapper, silky material, notes of hay, fresh butter and almond, with a strength that lovers of full-bodied cigars judge non-existent and that everyone else finds exactly where it should be.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Quai d''Orsay'
