UNION ALL SELECT 'Quai d''Orsay', 'es', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('El resultado es una de las ligas más claras del portafolio cubano — capa rubia, materia sedosa, notas de heno, mantequilla fresca y almendra, con una fuerza que los amantes de lo fuerte juzgan inexistente y que los demás encuentran exactamente en su sitio.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Quai d''Orsay'
UNION ALL SELECT 'Quai d''Orsay', 'de', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Die Seite des Hauses beschreibt weder ein Deckblatt noch Geschmacksnoten. Wikipedia, die eine einzige Quelle einräumt, schreibt, die Coronas habe es bis Ende der 1980er Jahre in zwei Deckblatttönen gegeben, Claro und Claro Claro, wobei der zweite mit dem Niedergang der hellen Deckblätter aufgegeben wurde.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Quai d''Orsay'
UNION ALL SELECT 'Quai d''Orsay', 'de', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Das Ergebnis ist einer der hellsten Blends des kubanischen Sortiments — blondes Deckblatt, seidige Substanz, Noten von Heu, frischer Butter und Mandel, mit einer Kraft, die Liebhaber kräftiger Zigarren für nicht vorhanden halten und die alle anderen genau am richtigen Platz finden.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Quai d''Orsay'
