UNION ALL SELECT 'Quai d''Orsay', 'ar', 'histoire 3 (nouveau texte)', (LOCATE(CAST('تكتب Habanos أنّ العلامة بقيت ما يزيد على أربعين عاماً قليلة الانتشار، معروفة في الأساس لدى خبراء السوق الفرنسية، ثمّ استأنفت مسيرتها بقياسين جديدين يُوزَّعان دولياً: No. 50 (110 mm، cepo 50) وNo. 54 (135 mm، cepo 54). وتعدّ الصفحة أربع إصدارات إقليمية محصورة بفرنسا، منها Secreto Cubano لسنة 2016 (40 x 110 mm)؛ وأعلنت الصحافة المتخصّصة في 2 أكتوبر 2018 عن Capitolio، 6 1/2 بوصة على cepo 54، بإنتاج 15 000 علبة من عشرة، وقد لُفّت أولى دفعاتها في مصنع Partagás.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'Quai d''Orsay'
UNION ALL SELECT 'Quai d''Orsay', 'ar', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('وظلّت العلامة طويلاً حكراً على السوق الفرنسية، ولم تُوزَّع على نطاق أوسع إلا اعتباراً من عشرينيات الألفية، مع مقاسات جديدة أسمك رفعت الشدّة قليلاً دون أن تغيّر المزاج. ومنحها هذا الانفتاح شباباً ثانياً لدى مدخّنين لم يكونوا يعرفونها إلا بالاسم.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'Quai d''Orsay'
