UNION ALL SELECT 'San Cristóbal de La Habana', 'de', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Die Marke greift den ursprünglichen Namen Havannas auf, den die Seite des Hauses auf 1519 zurückführt: San Cristóbal de La Habana. 1999 aufgelegt, zu Ehren der Geschichte der Stadt (am 20. November in Havanna, sagt Wikipedia), benannte sie ihre ersten vier Formate nach Festungen Havannas aus dem 16. bis 18. Jahrhundert: El Morro, La Fuerza, La Punta, El Príncipe.' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'San Cristóbal de La Habana'
UNION ALL SELECT 'San Cristóbal de La Habana', 'de', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Die Marke trägt den vollständigen Namen, den die Spanier der Stadt 1519 gaben: San Cristóbal de La Habana. 1999 zum vierhundertachtzigsten Jahrestag der Gründung aufgelegt, benannte sie ihre Formate nach den vier Festungen, die die Bucht bewachten — El Morro, La Punta, La Fuerza, El Príncipe.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'San Cristóbal de La Habana'
UNION ALL SELECT 'San Cristóbal de La Habana', 'zh', 'histoire 1 (nouveau texte)', (LOCATE(CAST('这个品牌沿用了哈瓦那的原名，品牌方页面称其可追溯到1519年：San Cristóbal de La Habana。它于1999年推出，向这座城市的历史致敬（据维基百科，在哈瓦那是11月20日），并以十六至十八世纪哈瓦那的几座要塞为首批四款规格命名：El Morro、La Fuerza、La Punta、El Príncipe。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'San Cristóbal de La Habana'
UNION ALL SELECT 'San Cristóbal de La Habana', 'zh', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('这个品牌沿用了西班牙人在1519年赋予这座城市的全名：圣克里斯托瓦尔·德拉哈瓦那。它于1999年为建城四百八十周年而推出，并以守卫海湾的四座要塞为其尺寸命名——莫罗、拉蓬塔、拉富埃尔萨、王子堡。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'San Cristóbal de La Habana'
UNION ALL SELECT 'San Cristóbal de La Habana', 'ar', 'histoire 1 (nouveau texte)', (LOCATE(CAST('تستعيد العلامة الاسم الأصلي لهافانا، الذي تُرجعه صفحة الدار إلى سنة 1519: San Cristóbal de La Habana. أُطلقت سنة 1999 تكريماً لتاريخ المدينة (في 20 نوفمبر في هافانا، كما تقول ويكيبيديا)، وسمّت قياساتها الأربعة الأولى على قلاع من هافانا تعود إلى القرون من السادس عشر إلى الثامن عشر: El Morro وLa Fuerza وLa Punta وEl Príncipe.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'San Cristóbal de La Habana'
UNION ALL SELECT 'San Cristóbal de La Habana', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('تحمل العلامة الاسم الكامل الذي منحه الإسبان للمدينة سنة 1519: سان كريستوبال دي لا هابانا. أُطلقت سنة 1999 في الذكرى الأربعمئة والثمانين للتأسيس، وسمّت مقاساتها على القلاع الأربع التي كانت تحرس الخليج — إل مورو، لا بونتا، لا فويرسا، إل برينسيبي.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'San Cristóbal de La Habana'
UNION ALL SELECT 'San Cristóbal de La Habana', 'fr', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Habanos classe la marque en force légère à moyenne, roulée totalement à la main en tripe longue, avec capote et tripe de la zone de Vuelta Abajo ; la page ne décrit aucune note de goût. Wikipédia ajoute qu''une marque du même nom existait avant la Révolution, sans lien avec la nouvelle.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'San Cristóbal de La Habana'
UNION ALL SELECT 'San Cristóbal de La Habana', 'fr', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('L''assemblage a été conçu pour un registre médium, avec une matière plus douce que celle des grandes marques corsées et une aromatique tournée vers le cèdre, le café au lait et une note minérale peu commune dans le portefeuille cubain. C''est une marque de la fin du XXe siècle, et cela s''entend : elle a été composée à une époque où Habanos cherchait à élargir son offre vers des profils accessibles.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'San Cristóbal de La Habana'
