UNION ALL SELECT 'La Flor de Cano', 'fr', 'factory', (CAST(`factory` AS BINARY) = CAST('La Corona (Miguel Fernández Roig, Cerro) selon la presse du métier (2011) ; Habanos ne nomme aucune fabrique ; Selectos No.3 de 2023 roulée à El Caney sous supervision de La Corona' AS BINARY)) FROM `brands` WHERE `name` = 'La Flor de Cano'
UNION ALL SELECT 'La Flor de Cano', 'fr', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Habanos, dans un communiqué du 26 mars 2015, la dit marque cubaine historique originaire de 1884, sans nommer de fondateur. Deux détaillants britanniques la datent de 1932 et l''attribuent à Juan Cano, dont l''un précise Juan Cano Sainz et son épouse Consuela, qui faisaient rouler les cigares sur leur table de cuisine : les deux versions divergent. Un détaillant britannique écrit que les formats courants ont longtemps été faits à la machine, puis que les cigares sont aujourd''hui entièrement faits à la main. Habanos présente pour sa part la gamme comme roulée totalement à la main, en tripe courte, avec la vitola Elegidos, et la marque a signé des éditions régionales : Short Robusto pour le Royaume-Uni (2010), Siboney pour le Canada (2015), Selectos No.3 pour le Royaume-Uni (2023).' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'La Flor de Cano'
UNION ALL SELECT 'La Flor de Cano', 'fr', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Fondée en 1884 par les frères Cano, la maison a connu au XXe siècle une production régulière puis un effacement progressif. Sa gamme courante s''est réduite à presque rien, et l''essentiel de ce qui porte aujourd''hui son nom paraît sous forme d''éditions régionales — ces séries composées pour un marché national précis, que les collectionneurs suivent de près.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'La Flor de Cano'
UNION ALL SELECT 'La Flor de Cano', 'en', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Habanos, in a press release of 26 March 2015, calls it a historic Cuban brand originating in 1884, without naming a founder. Two British retailers date it to 1932 and credit it to Juan Cano, one of them specifying Juan Cano Sainz and his wife Consuela, who had the cigars rolled on their kitchen table: the two versions diverge. A British retailer writes that the standard formats were long machine-made, and that the cigars are now entirely hand-made. Habanos for its part presents the range as rolled totally by hand, with short filler, with the Elegidos vitola, and the brand has put out regional editions: Short Robusto for the United Kingdom (2010), Siboney for Canada (2015), Selectos No.3 for the United Kingdom (2023).' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'La Flor de Cano'
UNION ALL SELECT 'La Flor de Cano', 'en', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Founded in 1884 by the Cano brothers, the house saw steady production through the twentieth century and then a gradual fading. Its regular range has shrunk to almost nothing, and most of what carries its name today appears as regional editions — those series composed for one specific national market, which collectors follow closely.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'La Flor de Cano'
UNION ALL SELECT 'La Flor de Cano', 'es', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Habanos, en un comunicado del 26 de marzo de 2015, la dice marca cubana histórica originaria de 1884, sin nombrar a un fundador. Dos minoristas británicos la datan de 1932 y se la atribuyen a Juan Cano, uno de los cuales precisa Juan Cano Sainz y su esposa Consuela, que hacían liar los puros en la mesa de su cocina: las dos versiones divergen. Un minorista británico escribe que los formatos corrientes se hicieron durante mucho tiempo a máquina, y que hoy los puros se hacen enteramente a mano. Habanos presenta por su parte la gama como liada totalmente a mano, con tripa corta, con la vitola Elegidos, y la marca ha firmado ediciones regionales: Short Robusto para el Reino Unido (2010), Siboney para Canadá (2015), Selectos No.3 para el Reino Unido (2023).' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'La Flor de Cano'
UNION ALL SELECT 'La Flor de Cano', 'es', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('Fundada en 1884 por los hermanos Cano, la casa conoció en el siglo XX una producción regular y después un borrado progresivo. Su gama corriente se ha reducido a casi nada, y lo esencial de lo que hoy lleva su nombre aparece en forma de ediciones regionales — esas series compuestas para un mercado nacional preciso, que los coleccionistas siguen de cerca.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'La Flor de Cano'
UNION ALL SELECT 'La Flor de Cano', 'de', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Habanos nennt sie in einer Mitteilung vom 26. März 2015 eine historische kubanische Marke, die auf 1884 zurückgeht, ohne einen Gründer zu nennen. Zwei britische Einzelhändler datieren sie auf 1932 und schreiben sie Juan Cano zu, einer von ihnen präzisiert Juan Cano Sainz und seine Frau Consuela, die die Zigarren auf ihrem Küchentisch rollen ließen: Die beiden Versionen weichen voneinander ab. Ein britischer Einzelhändler schreibt, die gängigen Formate seien lange maschinell gefertigt worden, die Zigarren würden heute aber vollständig von Hand gefertigt. Habanos stellt die Palette seinerseits als völlig handgerollt dar, mit Shortfiller, mit der Vitola Elegidos, und die Marke hat regionale Editionen herausgebracht: Short Robusto für das Vereinigte Königreich (2010), Siboney für Kanada (2015), Selectos No.3 für das Vereinigte Königreich (2023).' AS BINARY), CAST(`history_de` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'La Flor de Cano'
UNION ALL SELECT 'La Flor de Cano', 'de', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('1884 von den Brüdern Cano gegründet, erlebte das Haus im 20. Jahrhundert eine stetige Produktion und dann ein allmähliches Verschwinden. Sein laufendes Sortiment ist auf fast nichts geschrumpft, und das meiste, was heute seinen Namen trägt, erscheint als Regionaledition — jene Serien, die für einen bestimmten nationalen Markt komponiert werden und denen Sammler aufmerksam folgen.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'La Flor de Cano'
UNION ALL SELECT 'La Flor de Cano', 'zh', 'histoire 1 (nouveau texte)', (LOCATE(CAST('Habanos 在2015年3月26日的新闻稿中称它是源自1884年的古巴历史品牌，未点出创始人。两家英国零售商称它始于1932年，出自 Juan Cano，其中一家写明是 Juan Cano Sainz 和他的妻子 Consuela，两人曾让人在自家厨房的桌子上卷制雪茄：两种说法不一。一家英国零售商写道，常规规格长期是机器制作的，如今雪茄则完全手工制作。Habanos 则把该系列介绍为全手工卷制、短茄芯，并含 Elegidos 规格；该品牌还推出过地区限定版：面向英国的 Short Robusto（2010年）、面向加拿大的 Siboney（2015年）、面向英国的 Selectos No.3（2023年）。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'La Flor de Cano'
UNION ALL SELECT 'La Flor de Cano', 'zh', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('这家1884年由卡诺兄弟创立的企业，在二十世纪有过稳定的生产，随后逐渐淡出。它的常规产品线已缩减到几乎为零，如今冠以其名的多半以地区限定版形式出现——那些为某个具体国家市场而调配的系列，收藏者对此紧盯不放。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'La Flor de Cano'
UNION ALL SELECT 'La Flor de Cano', 'ar', 'histoire 1 (nouveau texte)', (LOCATE(CAST('تقول Habanos في بيان صدر في 26 مارس 2015 إنها علامة كوبية تاريخية يعود أصلها إلى 1884، من دون أن تسمّي مؤسِّسًا. ويقول تاجرا تجزئة بريطانيان إنها تعود إلى عام 1932 وتُنسب إلى Juan Cano، ويحدّد أحدهما أنه Juan Cano Sainz وزوجته Consuela، اللذان كانا يجعلان السيجار يُلفّ على طاولة مطبخهما: والروايتان متباينتان. ويكتب تاجر تجزئة بريطاني إنّ القياسات الجارية ظلّت مدّة طويلة تُصنع بالآلة، ثم إنّ السيجار يُصنع اليوم بالكامل باليد. وتقدّم Habanos من جهتها المجموعة على أنها ملفوفة كليًّا باليد، بحشوة قصيرة، مع قياس Elegidos، وقد أصدرت العلامة إصدارات إقليمية: Short Robusto للمملكة المتحدة (2010)، وSiboney لكندا (2015)، وSelectos No.3 للمملكة المتحدة (2023).' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'La Flor de Cano'
UNION ALL SELECT 'La Flor de Cano', 'ar', 'histoire 1 (ancien texte parti)', (LOCATE(CAST('أسّسها الأخوان كانو سنة 1884، وعرفت الدار في القرن العشرين إنتاجاً منتظماً ثم انحساراً تدريجياً. تقلّصت تشكيلتها الجارية إلى ما يقارب العدم، ومعظم ما يحمل اسمها اليوم يصدر في هيئة إصدارات إقليمية — تلك السلاسل المؤلَّفة لسوق وطنية بعينها، ويتابعها الجامعون عن كثب.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'La Flor de Cano'
UNION ALL SELECT 'La Flor de Cano', 'fr', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Un détaillant britannique la dit difficile à trouver, la production étant restreinte. Habanos la donne de force moyenne, avec un tabac de la zone de Vuelta Abajo ; des détaillants citent aussi des tabacs de Vuelta Abajo et de Semi Vuelta.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'La Flor de Cano'
UNION ALL SELECT 'La Flor de Cano', 'fr', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Ce statut lui vaut une réputation particulière : celle d''une marque qu''on ne trouve pas, et dont chaque sortie est guettée. Le profil, lui, est resté fidèle à son époque — doux à médium, cèdre, foin, une note de pain d''épice, sans la puissance que les assemblages récents recherchent.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'La Flor de Cano'
UNION ALL SELECT 'La Flor de Cano', 'en', 'histoire 2 (nouveau texte)', (LOCATE(CAST('A British retailer says it is hard to find, production being limited. Habanos gives it as medium in strength, with tobacco from the Vuelta Abajo area; retailers also cite tobaccos from Vuelta Abajo and Semi Vuelta.' AS BINARY), CAST(`history_en` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'La Flor de Cano'
UNION ALL SELECT 'La Flor de Cano', 'en', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('That status earns it a particular reputation: a brand you cannot find, and whose every release is watched for. The profile has stayed faithful to its era — mild to medium, cedar, hay, a note of gingerbread, without the power recent blends look for.' AS BINARY), CAST(`history_en` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'La Flor de Cano'
UNION ALL SELECT 'La Flor de Cano', 'es', 'histoire 2 (nouveau texte)', (LOCATE(CAST('Un minorista británico la dice difícil de encontrar, por ser restringida la producción. Habanos la da de fuerza media, con tabaco de la zona de Vuelta Abajo; los minoristas citan también tabacos de Vuelta Abajo y de Semi Vuelta.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'La Flor de Cano'
UNION ALL SELECT 'La Flor de Cano', 'es', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Ese estatus le vale una reputación particular: la de una marca que no se encuentra y cuya cada salida se acecha. El perfil, en cambio, ha seguido fiel a su época — suave a medio, cedro, heno, una nota de pan de especias, sin la potencia que buscan las ligas recientes.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'La Flor de Cano'
