UNION ALL SELECT 'La Flor de Cano', 'de', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('Dieser Status verschafft ihm einen besonderen Ruf: den einer Marke, die man nicht findet und deren jede Ausgabe erwartet wird. Das Profil ist seiner Zeit treu geblieben — mild bis mittel, Zeder, Heu, eine Note Lebkuchen, ohne die Kraft, die neuere Blends suchen.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'La Flor de Cano'
UNION ALL SELECT 'La Flor de Cano', 'zh', 'histoire 2 (nouveau texte)', (LOCATE(CAST('一家英国零售商称它不易买到，因产量有限。Habanos 给出的浓度为中等，用的是 Vuelta Abajo 产区的烟草；零售商也提到 Vuelta Abajo 和 Semi Vuelta 的烟草。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'La Flor de Cano'
UNION ALL SELECT 'La Flor de Cano', 'zh', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('这一处境为它赢得了一种特殊的名声：一个买不到的品牌，而它每一次出品都有人守候。风格则忠于它的年代——柔至中度，雪松、干草，一丝姜饼气息，没有近年配方所追逐的力度。' AS BINARY), CAST(`history_zh` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'La Flor de Cano'
UNION ALL SELECT 'La Flor de Cano', 'ar', 'histoire 2 (nouveau texte)', (LOCATE(CAST('يقول تاجر تجزئة بريطاني إنها يصعب العثور عليها، لأنّ الإنتاج محدود. وتعطيها Habanos قوة متوسطة، بتبغ من منطقة Vuelta Abajo؛ ويذكر تجار التجزئة أيضًا تبغًا من Vuelta Abajo ومن Semi Vuelta.' AS BINARY), CAST(`history_ar` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'La Flor de Cano'
UNION ALL SELECT 'La Flor de Cano', 'ar', 'histoire 2 (ancien texte parti)', (LOCATE(CAST('ويمنحها هذا الوضع سمعة خاصة: علامة لا تُوجَد، ويُترقَّب كل إصدار لها. أمّا الطابع فبقي وفيّاً لزمنه — لطيف إلى متوسط، أرز وقشّ ونفحة خبز التوابل، بلا القوّة التي تبحث عنها الخلطات الحديثة.' AS BINARY), CAST(`history_ar` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'La Flor de Cano'
UNION ALL SELECT 'La Flor de Cano', 'fr', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Un détaillant donne pour l''édition Selectos No.3 de 2023 un tirage de 125 000 cigares en 5 000 boîtes de 25 ; Habanos, pour Siboney (2015), 2 000 boîtes de 25.' AS BINARY), CAST(`history` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'La Flor de Cano'
UNION ALL SELECT 'La Flor de Cano', 'fr', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('C''est le genre de maison dont l''existence tient à peu de chose : quelques milliers de cigares par an, et une place sur une liste officielle.' AS BINARY), CAST(`history` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'La Flor de Cano'
