UNION ALL SELECT 'La Flor de Cano', 'es', 'histoire 3 (nouveau texte)', (LOCATE(CAST('Un minorista da para la edición Selectos No.3 de 2023 una tirada de 125 000 puros en 5 000 cajas de 25; Habanos, para Siboney (2015), 2 000 cajas de 25.' AS BINARY), CAST(`history_es` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'La Flor de Cano'
UNION ALL SELECT 'La Flor de Cano', 'es', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Es el tipo de casa cuya existencia pende de muy poco: unos miles de cigarros al año, y un lugar en una lista oficial.' AS BINARY), CAST(`history_es` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'La Flor de Cano'
