UNION ALL SELECT 'La Flor de Cano', 'de', 'histoire 3 (ancien texte parti)', (LOCATE(CAST('Es ist die Art Haus, dessen Fortbestehen an wenigem hängt: ein paar tausend Zigarren im Jahr und ein Platz auf einer offiziellen Liste.' AS BINARY), CAST(`history_de` AS BINARY)) = 0) FROM `brands` WHERE `name` = 'La Flor de Cano'
UNION ALL SELECT 'La Flor de Cano', 'zh', 'histoire 3 (nouveau texte)', (LOCATE(CAST('一家零售商给出2023年 Selectos No.3 版的发行量为125 000支雪茄、5 000盒，每盒25支；Habanos 给出 Siboney（2015年）为2 000盒，每盒25支。' AS BINARY), CAST(`history_zh` AS BINARY)) > 0) FROM `brands` WHERE `name` = 'La Flor de Cano'
