UNION ALL SELECT 'Trinidad', 'en', 'gamme Robustos Extra (vitolas)', (JSON_LENGTH(JSON_EXTRACT(`gamme_en`, '$[3].vitolas')) = 2) FROM `brands` WHERE `name` = 'Trinidad'
UNION ALL SELECT 'Trinidad', 'en', 'gamme Robustos Extra (texte)', (CAST(JSON_UNQUOTE(JSON_EXTRACT(`gamme_en`, '$[3].story')) AS BINARY) = CAST('A vitola of ring gauge 50 x 155 mm, presented in 2003, in boxes of 12 and 24 and in packs of 3, says habanos.com, whose brand page also dates the Robustos T to 2009 (without giving their dimensions; Wikipedia lists them at 4 7/8 inches x 50). The Robustos Extra, discontinued earlier according to the trade press, returned to regular production in February 2024 for the brand''s 55th anniversary (6 1/8 inches x cepo 50, boxes of 12 and of 3, new presentation). The current status of the Robustos T is not established by any page read.' AS BINARY)) FROM `brands` WHERE `name` = 'Trinidad'
