UNION ALL SELECT 'Trinidad', 'es', 'gamme Robustos Extra (vitolas)', (JSON_LENGTH(JSON_EXTRACT(`gamme_es`, '$[3].vitolas')) = 2) FROM `brands` WHERE `name` = 'Trinidad'
UNION ALL SELECT 'Trinidad', 'es', 'gamme Robustos Extra (texte)', (CAST(JSON_UNQUOTE(JSON_EXTRACT(`gamme_es`, '$[3].story')) AS BINARY) = CAST('Vitola de cepo 50 x 155 mm, presentada en 2003, en cofres de 12 y 24 y en paquetes de 3, dice habanos.com, cuya página de marca fecha también en 2009 los Robustos T (sin dar sus medidas; Wikipedia los lista en 4 7/8 pulgadas x 50). Los Robustos Extra, retirados antes según la prensa del oficio, volvieron a la producción regular en febrero de 2024 por los 55 años de la marca (6 1/8 pulgadas x cepo 50, cajas de 12 y de 3, nueva presentación). El estado actual de los Robustos T no lo establece ninguna página leída.' AS BINARY)) FROM `brands` WHERE `name` = 'Trinidad'
