UNION ALL SELECT 'Trinidad', 'de', 'gamme Robustos Extra (texte)', (CAST(JSON_UNQUOTE(JSON_EXTRACT(`gamme_de`, '$[3].story')) AS BINARY) = CAST('Vitola mit Ringmaß 50 x 155 mm, 2003 vorgestellt, in Kisten zu 12 und 24 und in Päckchen zu 3, sagt habanos.com, dessen Markenseite außerdem die Robustos T auf 2009 datiert (ohne ihre Maße anzugeben; Wikipedia führt sie mit 4 7/8 Zoll x 50 auf). Die Robustos Extra, zuvor laut Fachpresse eingestellt, kehrten im Februar 2024 zum 55-jährigen Bestehen der Marke in die reguläre Produktion zurück (6 1/8 Zoll x cepo 50, Kisten zu 12 und zu 3, neue Aufmachung). Der aktuelle Status der Robustos T ist durch keine gelesene Seite belegt.' AS BINARY)) FROM `brands` WHERE `name` = 'Trinidad'
