UNION ALL SELECT 'Trinidad', 'ar', 'gamme Robustos Extra (vitolas)', (JSON_LENGTH(JSON_EXTRACT(`gamme_ar`, '$[3].vitolas')) = 2) FROM `brands` WHERE `name` = 'Trinidad'
UNION ALL SELECT 'Trinidad', 'ar', 'gamme Robustos Extra (texte)', (CAST(JSON_UNQUOTE(JSON_EXTRACT(`gamme_ar`, '$[3].story')) AS BINARY) = CAST('قياس حلقي 50 x 155 مم، قُدّم عام 2003، في علب من 12 و24 وفي رزم من 3، بحسب موقع habanos.com الذي تؤرّخ صفحة العلامة فيه أيضًا Robustos T بعام 2009 (من دون ذكر مقاساتها؛ وتدرجها ويكيبيديا بـ 4 7/8 بوصة x 50). وقد عاد Robustos Extra، الذي توقّف قبل ذلك بحسب الصحافة المتخصّصة، إلى الإنتاج المنتظم في فبراير 2024 بمناسبة مرور 55 عامًا على العلامة (6 1/8 بوصة x cepo 50، علب من 12 ومن 3، تقديم جديد). أما الوضع الحالي لـRobustos T فلا تثبته أي صفحة مقروءة.' AS BINARY)) FROM `brands` WHERE `name` = 'Trinidad'
