UNION ALL SELECT 'pays cuba', 'fr', 'desc La Gloria Cubana', (LOCATE(CAST('Fondée en 1885 ; série Medaille d''Or ; tripe longue ; fabrique Partagás selon la presse du métier' AS BINARY), CAST(`brands` AS BINARY)) > 0) FROM `producer_countries` WHERE `id` = 'cuba'
UNION ALL SELECT 'pays cuba', 'fr', 'desc Juan López', (LOCATE(CAST('Années 1870 selon Habanos (1876 selon Wikipédia) ; Selección No. 1, No. 2 et Selección Especial' AS BINARY), CAST(`brands` AS BINARY)) > 0) FROM `producer_countries` WHERE `id` = 'cuba'
