UNION ALL SELECT 'pays cuba', 'fr', 'desc Rafael González', (LOCATE(CAST('Années 1930 selon Habanos ; avis de dégustation sous le couvercle des boîtes ; fabrique non nommée' AS BINARY), CAST(`brands` AS BINARY)) > 0) FROM `producer_countries` WHERE `id` = 'cuba'
