UNION ALL SELECT 'pays cuba', 'fr', 'desc Saint Luis Rey', (LOCATE(CAST('Avant la Seconde Guerre mondiale selon Habanos (1940 selon Wikipédia) ; nom de San Luis, hypothèse de Habanos' AS BINARY), CAST(`brands` AS BINARY)) > 0) FROM `producer_countries` WHERE `id` = 'cuba'
